const STORAGE_KEYS = {cart:'pashuGhar.cart.v1',wishlist:'pashuGhar.wishlist.v1',booking:'pashuGhar.booking.v1',enquiries:'pashuGhar.enquiries.v1',appointments:'pashuGhar.appointments.v1',subscriptions:'pashuGhar.subscriptions.v1',orders:'pashuGhar.orders.v1',newsletter:'pashuGhar.newsletter.v1'};
const readStorage = (key, fallback) => { try { const v = localStorage.getItem(key); return v ? JSON.parse(v) : fallback; } catch { return fallback; } };
const writeStorage = (key, value) => { try { localStorage.setItem(key, JSON.stringify(value)); return true; } catch { return false; } };
const STORE = {
  cart: readStorage(STORAGE_KEYS.cart, []), wishlist: readStorage(STORAGE_KEYS.wishlist, []), booking: readStorage(STORAGE_KEYS.booking, null),
  enquiries: readStorage(STORAGE_KEYS.enquiries, []), appointments: readStorage(STORAGE_KEYS.appointments, []), subscriptions: readStorage(STORAGE_KEYS.subscriptions, []), orders: readStorage(STORAGE_KEYS.orders, []),
  filters: {live:{species:'all',district:'all',vet:false,sort:'featured',maxPrice:200000,breed:'all',age:'all',weight:'all'},meat:{category:'all',cut:'all',method:[],maxPrice:5500,sale:false,stock:true,sort:'featured'},produce:{category:'all',maxPrice:3000,sort:'featured'},supplies:{petType:'all',size:'all',brand:'all',maxPrice:5000,sort:'featured'},pets:{species:'all',listingType:'all',sort:'featured'},vets:{specialization:'all',city:'all',visitType:'all',availability:'all'},learn:{category:'all'}},
  listLimits:{live:8,meat:12,produce:12,supplies:12,pets:8,vets:8,learn:6}, searchQuery:'', currentQuickMode:'meat', cartReturnHash:'#home', lastFocus:null, toastTimer:null, testimonialIndex:0
};

// ============================== UTILITIES ==============================
const $ = (selector, root=document) => root.querySelector(selector);
const $$ = (selector, root=document) => [...root.querySelectorAll(selector)];
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const safeAttr = value => escapeHTML(value);
const formatPrice = value => `${CONFIG.currencySymbol} ${new Intl.NumberFormat('en-NP',{maximumFractionDigits:0}).format(Math.round(Number(value)||0))}`;
const priceWithUnit = (value, unit='') => `${formatPrice(value)}${unit ? ` / ${escapeHTML(unit)}` : ''}`;
const getProduct = id => PRODUCTS.find(p=>p.id===id);
const getAnimal = id => LIVE_ANIMALS.find(a=>a.id===id);
const getPet = id => PETS.find(p=>p.id===id);
const getVet = id => VETS.find(v=>v.id===id);
const getPost = id => POSTS.find(p=>p.id===id);
const keySlug = value => String(value||'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const todayISO = () => { const d=new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
const randomId = prefix => `${prefix}-${Date.now().toString(36).toUpperCase()}-${Math.random().toString(36).slice(2,6).toUpperCase()}`;
const imageAlt = item => `${item.name || item.breed || item.title || 'Pashu Ghar listing'}`;
const departmentMeta = key => CONFIG.departments[key] || {label:key,accent:CONFIG.departments.meat.accent,soft:CONFIG.departments.meat.soft,intro:''};
const setAccent = key => { const d=departmentMeta(key); document.documentElement.style.setProperty('--accent',d.accent);document.documentElement.style.setProperty('--accent-soft',d.soft); };
const iconSVG = name => {
  const paths={Curry:'<path d="M4 10h16l-1 8H5l-1-8Z"/><path d="M7 10a5 5 0 0 1 10 0M8 5l1-2m6 2 1-2"/>',Grill:'<path d="M4 8h16M6 8l-1 9h14l-1-9M8 12h8M8 15h8M7 4l2 2m6-2 2 2"/>',Fry:'<path d="M4 12h16l-2 6H6l-2-6ZM7 12V7h10v5M9 4c2-2 4 2 6 0"/>',Soup:'<path d="M4 12h16l-2 7H6l-2-7ZM3 12h18M8 8c-2-2 2-2 0-4m5 4c-2-2 2-2 0-4m5 4c-2-2 2-2 0-4"/>',Roast:'<path d="M6 14c-2-3 1-7 6-7s8 4 6 7l-3 4H9l-3-4Z"/><path d="M12 7V4M9 11h6"/>'};
  return `<span class="cook-icon" title="${escapeHTML(name)}"> <svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||'<circle cx="12" cy="12" r="8"/>'}</svg></span>`;
};
// Shared outline-style animal family illustration. Stroke-only currentColor, reused throughout the site.
const animalLineArt = (className='animal-line-svg') => `<svg class="${className}" viewBox="0 0 360 145" role="img" aria-label="Line illustration of a sheep, pig, cow, goat and hen behind a fence" xmlns="http://www.w3.org/2000/svg"><g fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M7 112H353M20 112v22m320-22v22M40 121h278"/><g><path d="M21 72q-9-9-1-18 1-13 17-9 7-12 18-4 13-1 13 12 12 5 5 18l-7 21H31Z"/><path d="M27 53l-7-10m33 0 5-10M37 64h1m17 0h1M38 76q9 7 17 0M33 93l-2 19m34-19 2 19"/><path d="M83 65q-2-15 16-18l16 3q16-3 20 11l-4 26H89Z"/><path d="M88 53l-3-9m39 7 7-9M98 64h1m23 0h1M105 75h12M95 86l-2 26m40-26 2 26"/><path d="M149 62q-2-15 14-20l11-12 10 12q22-2 24 19l-4 29h-52Z"/><path d="M165 44l-7-7m27-1 8-7M162 58h1m27 0h1M169 73q9 7 18 0M160 91l-2 21m40-21 2 21"/><path d="M224 69q-4-15 12-20l8-12 9 11q17 2 18 17l-3 27h-40Z"/><path d="M233 49l-8-6m31 4 7-8M237 63h1m19 0h1M240 76q7 5 14 0M234 92l-2 20m31-20 2 20"/><path d="M286 82q-8-12 2-20l8-16 10 13q14 3 13 17l-2 15h-29Z"/><path d="M297 63l-3-9m13 10 7-7M298 77h1m11 0h1M300 86l-1 26m15-26 1 26"/><path d="M10 134h340"/></g></g></svg>`;
const emptyState = (title, text, actionLabel='Explore the marketplace', href='#home') => `<div class="empty-state"><div class="empty-art">${animalLineArt()}</div><h3>${escapeHTML(title)}</h3><p>${escapeHTML(text)}</p><a class="btn btn-primary btn-small" href="${safeAttr(href)}">${escapeHTML(actionLabel)} →</a></div>`;
const toast = message => { const node=$('#toast');if(!node)return;node.textContent=message;node.classList.add('visible');clearTimeout(STORE.toastTimer);STORE.toastTimer=setTimeout(()=>node.classList.remove('visible'),3000); };
const saveState = () => { writeStorage(STORAGE_KEYS.cart,STORE.cart);writeStorage(STORAGE_KEYS.wishlist,STORE.wishlist);writeStorage(STORAGE_KEYS.booking,STORE.booking);writeStorage(STORAGE_KEYS.enquiries,STORE.enquiries);writeStorage(STORAGE_KEYS.appointments,STORE.appointments);writeStorage(STORAGE_KEYS.subscriptions,STORE.subscriptions);writeStorage(STORAGE_KEYS.orders,STORE.orders); };
const validatePhone = value => /^\+?[0-9\s()-]{7,18}$/.test(String(value||'').trim()) && String(value).replace(/\D/g,'').length>=7;
const validateEmail = value => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(value||'').trim());
const fieldValue = (form,name) => String(new FormData(form).get(name)||'').trim();
const totalQty = () => STORE.cart.reduce((sum,line)=>sum+(Number(line.qty)||0),0);
const cartLines = () => STORE.cart.map(line=>{const product=getProduct(line.productId);return product?{...line,product,unitPrice:Number(line.unitPrice)||getUnitPrice(product,line.weight,line.variant),lineTotal:(Number(line.unitPrice)||getUnitPrice(product,line.weight,line.variant))*line.qty}:null;}).filter(Boolean);
const getUnitPrice = (product, weight=1, variant='') => {
  if(product.department==='meat' && product.basePricePerKg && !product.name.includes('Pack')) return Math.round(product.basePrice*Number(weight||1));
  if(product.cut==='Soil care' && product.bulkBaseQty) return Math.round(product.basePrice*(Number(weight||product.bulkBaseQty)/product.bulkBaseQty));
  return Number(product.basePrice)||0;
};
const computeTotals = () => { const lines=cartLines();const subtotal=lines.reduce((s,l)=>s+l.lineTotal,0);const discount=Math.round(subtotal*CONFIG.discountPercent/100);const postDiscount=subtotal-discount;const delivery=postDiscount>=CONFIG.freeDeliveryAbove||!lines.length?0:CONFIG.deliveryFee;const tax=Math.round(postDiscount*CONFIG.taxPercent/100);return {lines,subtotal,discount,delivery,tax,total:postDiscount+delivery+tax,remaining:Math.max(0,CONFIG.freeDeliveryAbove-postDiscount),progress:Math.min(100,postDiscount/CONFIG.freeDeliveryAbove*100)};};
const updateCounters = () => {const count=$('#cartCount'),w=$('#wishlistCount');if(count)count.textContent=totalQty();if(w)w.textContent=STORE.wishlist.length;const dc=$('#drawerCount');if(dc)dc.textContent=`(${totalQty()})`;};
const persistCart = () => {writeStorage(STORAGE_KEYS.cart,STORE.cart);updateCounters();renderCartDrawer();};
const addToCart = (productId, {weight=1,qty=1,variant='',subscription=null}={}) => { const product=getProduct(productId);if(!product)return toast('That item could not be found.');if(!product.inStock)return toast('This item is currently marked out of stock.');const unitPrice=getUnitPrice(product,weight,variant);const lineId=subscription?`sub-${randomId(productId)}`:`${productId}:${weight}:${variant}`;const existing=STORE.cart.find(line=>line.lineId===lineId);if(existing)existing.qty+=qty;else STORE.cart.push({lineId,productId,weight,qty,variant,unitPrice,type:subscription?'subscription':'product',subscription:subscription||null,createdAt:new Date().toISOString()});if(subscription){STORE.subscriptions=[...STORE.subscriptions,{...subscription,id:lineId,productId,productName:product.name,qty,unitPrice,status:'In cart'}];writeStorage(STORAGE_KEYS.subscriptions,STORE.subscriptions);}persistCart();toast(subscription?'Subscription added to your basket.':'Added to your basket.');};
const updateCartQty = (lineId,delta) => {const line=STORE.cart.find(l=>l.lineId===lineId);if(!line)return;line.qty=Math.max(1,Math.min(99,line.qty+delta));persistCart();};
const removeCartLine = lineId => {STORE.cart=STORE.cart.filter(l=>l.lineId!==lineId);STORE.subscriptions=STORE.subscriptions.filter(s=>s.id!==lineId);writeStorage(STORAGE_KEYS.subscriptions,STORE.subscriptions);persistCart();toast('Item removed from basket.');};
const toggleWishlist = id => {if(STORE.wishlist.includes(id))STORE.wishlist=STORE.wishlist.filter(x=>x!==id);else STORE.wishlist.push(id);writeStorage(STORAGE_KEYS.wishlist,STORE.wishlist);updateCounters();toast(STORE.wishlist.includes(id)?'Saved to your wishlist.':'Removed from your wishlist.');if(location.hash==='#wishlist')renderRoute();};
const saveEnquiry = enquiry => { STORE.enquiries.unshift({...enquiry,id:randomId('ENQ'),createdAt:new Date().toISOString(),status:'Saved in this browser'});writeStorage(STORAGE_KEYS.enquiries,STORE.enquiries);toast('Enquiry saved in My Pashu. Contact the seller to confirm.'); };
const routeTo = hash => { if(!hash.startsWith('#'))hash=`#${hash}`;location.hash=hash; };
const link = (hash, label, cls='') => `<a class="${cls}" href="${safeAttr(hash)}">${escapeHTML(label)}</a>`;
const imgTag = (src,alt,cls='',lazy=true) => `<img class="${safeAttr(cls)}" src="${safeAttr(src)}" alt="${safeAttr(alt)}" ${lazy?'loading="lazy"':''} decoding="async">`;
const optionsHTML = (items,selected='',firstLabel='Choose') => `${firstLabel!==null?`<option value="${/^(All|Any|Buy or adopt)/i.test(String(firstLabel))?'all':''}">${escapeHTML(firstLabel)}</option>`:''}${items.map(item=>{const val=typeof item==='string'?item:item.value;const label=typeof item==='string'?item:item.label;return `<option value="${safeAttr(val)}" ${String(selected)===String(val)?'selected':''}>${escapeHTML(label)}</option>`;}).join('')}`;
const headerArt = () => animalLineArt('');
const routeHeading = (key,description,extra='') => {const d=departmentMeta(key);return `<section class="route-heading" style="--accent:${d.accent};--accent-soft:${d.soft}"><div class="container route-heading-inner"><div><p class="eyebrow">${escapeHTML(d.label)}</p><h1>${escapeHTML(key==='learn'?'Learn & care':d.label)}</h1><p>${escapeHTML(description||d.intro)}</p>${extra}</div><div class="route-art" aria-hidden="true">${animalLineArt()}</div></div></section>`;};
const formatAge = a => a.ageLabel || a.age || '—';

// ============================== VIEWS ==================================
function renderHome(){setAccent('meat');const featureAnimals=LIVE_ANIMALS.filter(a=>a.featured).slice(0,3);const featureProducts=PRODUCTS.filter(p=>p.department==='meat'&&p.featured).slice(0,4);const produce=PRODUCTS.filter(p=>p.department==='produce').slice(0,4);const supply=PRODUCTS.filter(p=>p.department==='supplies'&&p.featured).slice(0,4);const vets=VETS.slice(0,4);const departments=[['01','Live animals','Cattle, buffalo, goats and more','live',IMAGES.cow],['02','Fresh meat','Cuts for weekday meals and celebrations','meat',IMAGES.buffalo],['03','Farm produce','Milk, eggs, honey and pantry favourites','produce',IMAGES.honey],['04','Pets & adoption','Find a companion, with care at the centre','pets',IMAGES.dog],['05','Supplies & toys','Everyday essentials for happy, healthy pets','supplies',IMAGES.supplies],['06','Vet care','Connect with a professional near you','vets',IMAGES.vet],['07','Learn & care','Helpful notes for animal wellbeing','learn',IMAGES.herd]];
return `<section class="hero"><div class="hero-inner"><div class="hero-copy-block"><p class="eyebrow">${escapeHTML(CONFIG.tagline)}</p><h1>Good care.<br><em>Good living.</em></h1><p class="hero-description">From the farm gate to the family home, find the animals, food, everyday essentials and care professionals that help animals thrive.</p><div class="hero-actions"><a class="btn btn-primary" href="#meat">Explore marketplace <span>↗</span></a><a class="btn btn-secondary" href="#vets">Book a vet <span>→</span></a></div><div class="hero-trust-note"><span>✳</span><div>For every animal,<br>at every stage of care.</div></div></div><div class="hero-art-wrap"><div class="hero-photo">${imgTag(IMAGES.herd,'Livestock grazing on a green farm','',false)}</div><div class="hero-sticker"><strong>FARM TO</strong><br>FAMILY<br>WITH CARE</div><div class="hero-animal-line">${animalLineArt()}</div></div></div></section>
<section class="quick-action-wrap"><div class="quick-action-card"><div class="booking-heading"><span class="eyebrow">A LITTLE HELP GETTING STARTED</span><strong>What brings you to Pashu Ghar?</strong></div><div class="quick-tabs" role="tablist" aria-label="Quick action"><button class="quick-tab" data-quick-mode="meat" role="tab" aria-selected="${STORE.currentQuickMode==='meat'}"><span>✦</span>Order meat</button><button class="quick-tab" data-quick-mode="animal" role="tab" aria-selected="${STORE.currentQuickMode==='animal'}"><span>♧</span>Find an animal</button><button class="quick-tab" data-quick-mode="vet" role="tab" aria-selected="${STORE.currentQuickMode==='vet'}"><span>✚</span>Book a vet</button></div><form class="quick-form" id="quickActionForm" data-mode="${safeAttr(STORE.currentQuickMode)}">${quickFields(STORE.currentQuickMode)}<button type="submit" class="btn btn-primary">${STORE.currentQuickMode==='meat'?'Browse fresh cuts':STORE.currentQuickMode==='animal'?'Find animals':'Find a vet'} <span>→</span></button></form></div></section>
<section class="department-index container" id="categories"><div class="section-heading"><div><p class="eyebrow">THE MARKETPLACE</p><h2>One home for <em>every need.</em></h2><p class="section-intro">A growing marketplace connecting farmers, families, animal lovers and care professionals.</p></div><a href="#about" class="text-link">Our approach <span>→</span></a></div><div class="department-list">${departments.map(([number,title,description,key,src])=>`<a class="department-row reveal" href="#${key}"><span class="department-number">${number}</span><div><h3>${escapeHTML(title)}</h3><p>${escapeHTML(description)}</p></div><div class="department-row-image">${imgTag(src,title)}</div><span class="row-cta"><span class="circle-arrow" aria-hidden="true">↗</span></span></a>`).join('')}</div></section><div class="animal-section-divider container" aria-hidden="true">${animalLineArt()}</div>
<section class="section featured-live"><div class="container"><div class="section-heading"><div><p class="eyebrow">FROM LOCAL FARMERS</p><h2>Find a healthy <em>herd.</em></h2><p class="section-intro">Browse seller listings, review the information provided, then arrange an in-person check.</p></div><a class="text-link" href="#live">See live animals <span>→</span></a></div><div class="cards-grid cols-3">${featureAnimals.map(renderLiveCard).join('')}</div></div></section>
<section class="section"><div class="container"><div class="section-heading"><div><p class="eyebrow">THE BUTCHER'S COUNTER</p><h2>Fresh cuts, <em>beautifully simple.</em></h2><p class="section-intro">Choose a cut, select a size and let the kitchen plans begin.</p></div><a class="text-link" href="#meat">Shop fresh meat <span>→</span></a></div><div class="cards-grid">${featureProducts.map(renderProductCard).join('')}</div></div></section>
<section class="section produce-feature"><div class="container produce-layout"><div class="produce-copy"><p class="eyebrow">FROM FARM TO FRIDGE</p><h2>Good mornings,<br><em>on repeat.</em></h2><p>Make everyday staples easier with fresh milk and farm eggs. Choose a daily, alternate-day or weekly subscription that suits your household.</p><div class="produce-note"><span>↻</span><div><strong>Subscriptions made simple</strong><br><small>Choose your rhythm and start date.</small></div></div><div class="subscription-ribbon"><div><strong>Stock up thoughtfully.</strong><small>Choose from milk, eggs, dairy, honey and more.</small></div><a class="circle-arrow" href="#produce" aria-label="Explore farm produce">↗</a></div></div><div class="cards-grid">${produce.map(renderProductCard).join('')}</div></div></section>
<section class="section"><div class="container"><div class="section-heading"><div><p class="eyebrow">ROOM FOR A NEW FRIEND</p><h2>Meet your <em>kind of pet.</em></h2></div><a href="#pets" class="text-link">Pets & adoption <span>→</span></a></div><div class="pet-category-grid">${[['Dogs',IMAGES.dog,'Dog'],['Cats',IMAGES.cat,'Cat'],['Birds',IMAGES.bird,'Bird'],['Small pets',IMAGES.pet,'Small pet']].map(([title,src,species])=>`<button class="pet-category" data-pet-species="${safeAttr(species)}">${imgTag(src,title)}<span><small>FIND YOUR MATCH</small><strong>${title}</strong></span></button>`).join('')}</div><div class="cards-grid cols-3" style="margin-top:22px">${PETS.filter(p=>p.featured).slice(0,3).map(renderPetCard).join('')}</div></div></section>
<section class="section section-tint"><div class="container"><div class="section-heading"><div><p class="eyebrow">LITTLE THINGS, BIG COMFORT</p><h2>Supplies for <em>everyday care.</em></h2><p class="section-intro">Helpful essentials, cozy corners and playful moments.</p></div><a href="#supplies" class="text-link">Shop supplies <span>→</span></a></div><div class="cards-grid">${supply.map(renderProductCard).join('')}</div></div></section>
<section class="section vets-section"><div class="container"><div class="section-heading"><div><p class="eyebrow">A TRUSTED HAND TO CALL</p><h2>Meet our <em>vets.</em></h2><p class="section-intro">Find a professional for routine care, a planned visit or advice. Confirm availability and registration directly.</p></div><a href="#vets" class="text-link">Find a vet <span>→</span></a></div><div class="cards-grid cols-2">${vets.map(renderVetCard).join('')}</div></div></section>
<section class="section"><div class="container"><div class="center-heading"><p class="eyebrow">GOOD CARE, GOOD FOUNDATIONS</p><h2>Trust is built with <em>care.</em></h2></div><div class="why-grid">${[['✓','Verified sellers','Seller verification should be completed before launch. Always confirm identity and ownership details.'],['♧','Health certificates','Ask for original health and vaccination records; badges are not medical guarantees.'],['❄','Cold-chain delivery','Perishable goods require appropriate safe handling and storage from dispatch to delivery.'],['♡','Secure payment','Use a trusted payment provider in a live launch; this front-end demo does not process payments.']].map(([icon,title,desc])=>`<article class="why-card reveal"><span class="why-icon">${icon}</span><h3>${title}</h3><p>${desc}</p></article>`).join('')}</div></div></section>
<section class="section how-section" id="how-it-works"><div class="container"><div class="center-heading"><p class="eyebrow">A SIMPLE WAY TO GET STARTED</p><h2>Good things happen <em>in four steps.</em></h2><p class="section-intro">Whether you are shopping for the family, finding an animal or arranging care, start with the details and confirm them before committing.</p></div><div class="steps-grid">${[['01','Browse with care','Compare products and listings, including the details shared by each seller.'],['02','Ask the right questions','Review health records, terms, prices and what is included in the listing.'],['03','Arrange the next step','Place a product order, request a visit, make an offer or book a vet slot.'],['04','Confirm directly','Wait for the provider or seller to confirm availability, fulfilment and final details.']].map(([n,title,desc])=>`<article class="step-card reveal"><span class="step-number">${n}</span><h3>${title}</h3><p>${desc}</p></article>`).join('')}</div><div class="animal-section-divider" aria-hidden="true">${animalLineArt()}</div></div></section>
<section class="section testimonial-section"><div class="container testimonial-wrap"><p class="eyebrow">A MARKETPLACE WITH AN ANIMAL-FIRST MINDSET</p><div class="testimonial-quote">“</div><blockquote id="testimonialText">${escapeHTML(TESTIMONIALS[0].quote)}</blockquote><div class="testimonial-author" id="testimonialAuthor">${escapeHTML(TESTIMONIALS[0].author)}</div><div class="testimonial-dots">${TESTIMONIALS.map((t,i)=>`<button class="testimonial-dot ${i===0?'active':''}" data-testimonial="${i}" aria-label="Show note ${i+1}"></button>`).join('')}</div></div></section>
<section class="section faq-section"><div class="container faq-layout"><div><p class="eyebrow">GOOD TO KNOW</p><h2>Questions worth<br><em>asking.</em></h2><p class="section-subtitle">Responsible choices start with clear details. If something matters, confirm it directly with the seller or your vet.</p><a href="#contact" class="text-link">Talk to us <span>→</span></a></div><div class="faq-list">${FAQ.map((f,i)=>`<details ${i===0?'open':''}><summary>${escapeHTML(f.q)}<span>+</span></summary><p>${escapeHTML(f.a)}</p></details>`).join('')}</div></div></section>
<section class="newsletter-section"><div class="container newsletter-inner"><div><p class="eyebrow">A LITTLE CARE IN YOUR INBOX</p><h2>Helpful notes. <em>Healthy lives.</em></h2><p>Get practical guides and occasional marketplace news.</p></div><form id="newsletterForm" class="newsletter-form"><label class="sr-only" for="newsletterEmail">Email address</label><input id="newsletterEmail" name="email" type="email" required placeholder="Your email address"><button type="submit" class="btn btn-primary">Keep me posted <span>→</span></button><small>Manage real email consent and mailing lists through a connected service before launch.</small></form></div></section>`;
}
function quickFields(mode){if(mode==='animal')return `<label class="field"><span>Species</span><select name="species">${optionsHTML(['Cattle','Buffalo','Goat','Sheep','Pig','Poultry','Fish'],'','Any species')}</select></label><label class="field"><span>District</span><select name="district">${optionsHTML(CONFIG.districts,'','Any district')}</select></label><label class="field"><span>Budget up to</span><select name="budget">${optionsHTML([{value:'20000',label:'Rs. 20,000'},{value:'50000',label:'Rs. 50,000'},{value:'100000',label:'Rs. 100,000'},{value:'200000',label:'Rs. 200,000+'}],'200000','Any budget')}</select></label>`;if(mode==='vet')return `<label class="field"><span>Animal type</span><select name="animalType">${optionsHTML(['Large animal','Small animal','Poultry','Aquatic'],'','Choose type')}</select></label><label class="field"><span>City</span><select name="city">${optionsHTML(CONFIG.cities,'','Choose city')}</select></label><label class="field"><span>Preferred date</span><input type="date" name="date" min="${todayISO()}" value="${todayISO()}" required></label>`;return `<label class="field"><span>Fulfilment</span><select name="fulfilment"><option>Delivery</option><option>Pick-Up</option></select></label><label class="field"><span>City / location</span><select name="city" required>${optionsHTML(CONFIG.cities,'','Choose city')}</select></label><label class="field"><span>Preferred date</span><input type="date" name="date" min="${todayISO()}" value="${todayISO()}" required></label><label class="field"><span>Time slot</span><select name="slot" required>${optionsHTML(CONFIG.timeSlots,'','Choose time')}</select></label>`;}
function renderLiveCard(a){const d=departmentMeta('live');return `<article class="entity-card" style="--accent:${d.accent};--accent-soft:${d.soft}"><a href="#animal/${safeAttr(a.id)}" class="card-image">${imgTag(a.image,`${a.breed}, ${a.species}`)}<span class="product-top-tags"><span class="badge department-badge">${escapeHTML(a.species)}</span></span></a><div class="card-body"><p class="card-overline">${escapeHTML(a.breed)}</p><h3>${link(`#animal/${a.id}`,a.breed)}</h3><div class="price-line"><span class="price">${formatPrice(a.price)}</span><small>${escapeHTML(a.priceUnit)}</small></div><div class="badge-row">${a.vetChecked?'<span class="badge success">✓ Vet-checked</span>':'<span class="badge">Vet check unlisted</span>'}${a.vaccinated?'<span class="badge success">✓ Vaccinated*</span>':''}</div><div class="entity-meta"><span>⌁ ${escapeHTML(a.district)}</span><span>◷ ${escapeHTML(formatAge(a))}</span><span>⚖ ${escapeHTML(a.weight)} kg</span></div><p>Seller: ${escapeHTML(a.seller)}</p><div class="card-actions"><a class="btn btn-primary btn-small" href="#animal/${a.id}">View listing <span>→</span></a></div></div></article>`;}
function renderProductCard(p){const d=departmentMeta(p.department);const isMeat=p.department==='meat'&&p.basePricePerKg;const unitPrice=getUnitPrice(p,isMeat?1:(p.bulkBaseQty||1));return `<article class="product-card" style="--accent:${d.accent};--accent-soft:${d.soft}" data-product-card="${safeAttr(p.id)}"><div class="card-image"><a href="#product/${safeAttr(p.id)}">${imgTag(p.image,p.name)}</a><div class="product-top-tags">${p.onSale?'<span class="badge danger">Offer</span>':''}${p.featured?'<span class="badge">Popular</span>':''}</div><button class="heart-button image-heart ${STORE.wishlist.includes(p.id)?'active':''}" data-action="wishlist" data-id="${safeAttr(p.id)}" aria-label="${STORE.wishlist.includes(p.id)?'Remove from':'Add to'} wishlist" aria-pressed="${STORE.wishlist.includes(p.id)}">♡</button></div><div class="card-body"><p class="card-overline">${escapeHTML(p.department==='meat'?p.categoryLabel:p.department==='produce'?'Farm source':p.petType)}</p><h3>${link(`#product/${p.id}`,p.name)}</h3>${p.department==='produce'?`<span class="source-label">✳ Farm source: ${escapeHTML(p.farmSource)}</span>`:''}<div class="price-line"><span class="price" data-live-price>${formatPrice(unitPrice)}</span>${p.oldPrice?`<span class="price-old">${formatPrice(p.oldPrice)}</span>`:''}<small>${isMeat?'/ kg':p.bulkBaseQty?`/${p.bulkBaseQty} kg`:p.department==='produce'?'':'/ item'}</small></div>${p.department==='meat'?`<div class="cook-row" aria-label="Cooking methods">${p.cookingMethods.slice(0,3).map(iconSVG).join('')}</div>`:''}${isMeat?`<label class="sr-only" for="weight-${p.id}">Select weight for ${escapeHTML(p.name)}</label><select class="product-weight-select" id="weight-${p.id}" data-weight-for="${p.id}"><option value="0.5">500 g</option><option value="1" selected>1 kg</option><option value="2">2 kg</option></select>`:''}${p.department==='supplies'?`<label class="sr-only" for="variant-${p.id}">Select size</label><select class="product-weight-select" id="variant-${p.id}" data-variant-for="${p.id}">${optionsHTML(p.sizes||['Standard'],p.sizes?.[0]||'Standard',null)}</select><label class="sr-only" for="color-${p.id}">Select colour</label><select class="product-weight-select" id="color-${p.id}" data-color-for="${p.id}">${optionsHTML(p.colors||['Natural'],'Natural',null)}</select>`:''}${p.subscription?`<div class="card-actions"><button class="btn btn-primary btn-small" data-action="subscribe" data-id="${p.id}">Set subscription →</button></div>`:p.cut==='Soil care'?`<label class="field" style="margin-top:8px"><span>Bulk quantity</span><select class="product-weight-select" data-bulk-qty-for="${p.id}">${p.bulkSizes.map(kg=>`<option value="${kg}" ${kg===p.bulkBaseQty?'selected':''}>${kg} kg</option>`).join('')}</select></label><p class="bulk-note">Minimum order: ${escapeHTML(p.minOrder||10)} kg. Contact the seller to confirm bulk delivery.</p><div class="card-actions"><button class="btn btn-primary btn-small" data-action="add" data-id="${p.id}">Add to basket</button></div>`:`<div class="weight-qty-row"><div class="qty-control" aria-label="Quantity"><button data-action="card-qty" data-id="${p.id}" data-delta="-1" aria-label="Decrease quantity">−</button><span data-qty-for="${p.id}">1</span><button data-action="card-qty" data-id="${p.id}" data-delta="1" aria-label="Increase quantity">+</button></div><button class="plain-link" data-action="quick-view" data-id="${p.id}">Quick view</button></div><button class="btn btn-primary btn-small add-product-btn" data-action="add" data-id="${p.id}" ${p.inStock?'':'disabled'}>${p.inStock?'Add to basket →':'Out of stock'}</button>`}</div></article>`;}
function renderPetCard(p){const d=departmentMeta('pets');return `<article class="entity-card" style="--accent:${d.accent};--accent-soft:${d.soft}"><a class="card-image" href="#animal/pet-${p.id}">${imgTag(p.image,`${p.name}, ${p.breed}`)}<span class="product-top-tags"><span class="badge department-badge">${escapeHTML(p.listingType)}</span></span></a><div class="card-body"><p class="card-overline">${escapeHTML(p.species)} · ${escapeHTML(p.gender)}</p><h3>${link(`#animal/pet-${p.id}`,`${p.name} · ${p.breed}`)}</h3><div class="price-line"><span class="price">${p.listingType==='Adopt'?'Adoption enquiry':formatPrice(p.price)}</span></div><div class="pet-card-status">${p.vaccinated?'<span class="badge success">Vaccination noted</span>':'<span class="badge">Vaccination unlisted</span>'}${p.dewormed?'<span class="badge success">Dewormed</span>':''}</div><p>${escapeHTML(p.temperament)}</p><div class="card-actions"><a class="btn btn-primary btn-small" href="#animal/pet-${p.id}">${p.listingType==='Adopt'?'Meet & enquire':'View pet'} →</a></div></div></article>`;}
function renderVetCard(v){const d=departmentMeta('vets');return `<article class="vet-card" style="--accent:${d.accent};--accent-soft:${d.soft}"><div class="vet-top">${imgTag(v.image,v.name,'vet-avatar')}<div><h3>${link(`#vet/${v.id}`,v.name)}</h3><span class="vet-specialty">${escapeHTML(v.specialization)}</span></div></div><p class="vet-info">${escapeHTML(v.experience)} years' experience<br>${escapeHTML(v.clinic)} · ${escapeHTML(v.city)}<br>Consultation from <strong>${formatPrice(v.fee)}</strong></p><div class="vet-meta"><span class="vet-rating">★ ${escapeHTML(v.rating)} <span class="muted-text">· ${escapeHTML(v.registration)}</span></span><a href="#vet/${v.id}" class="plain-link">View & book →</a></div></article>`;}
const introContent = {
 live:{title:'A better start at the farm gate',desc:'Listings are supplied for demonstration. Confirm seller identity, inspect the animal, ask for original health records and arrange appropriate transport before making a commitment.'},
 meat:{title:'Thoughtful cuts for everyday cooking',desc:'Choose the cut, select the pack size and check your basket. Prices and stock shown are sample values for this front-end demo.'},
 produce:{title:'Good things from local farms',desc:'Browse fresh staples and farm products. Subscription options are saved locally and need a real delivery/payment workflow before commercial use.'},
 pets:{title:'Companions deserve careful choices',desc:'Read each listing and meet the animal responsibly. Adoption and purchase listings are illustrative; confirm health and ownership details directly.'},
 supplies:{title:'Everyday essentials for happy pets',desc:'Find useful home, feeding, play and grooming essentials for your companion animals.'},
 vets:{title:'Care from people who know animals',desc:'Browse the directory and request an appointment. Verify each professional’s registration, credentials, hours and availability independently.'},
 learn:{title:'Notes for a more caring world',desc:'Practical guides about farm management, animal wellbeing, food handling and responsible pet ownership.'}
};
function sidebarHTML(dept){const f=STORE.filters[dept];if(dept==='live')return `<aside class="filter-sidebar" id="filterSidebar"><div class="filter-head"><strong>Refine listings</strong><button class="plain-link" data-action="clear-filters">Reset</button></div><div class="filter-group"><h3>Species</h3><select data-filter="species">${optionsHTML(['Cattle','Buffalo','Goat','Sheep','Pig','Poultry','Fish'].map(x=>({value:keySlug(x),label:x})),'all','All species').replace('<option value="">All species</option>','<option value="all">All species</option>')}</select></div><div class="filter-group"><h3>Breed</h3><select data-filter="breed">${optionsHTML([...new Set(LIVE_ANIMALS.map(a=>a.breed))].map(x=>({value:x,label:x})),'all','All breeds').replace('<option value="">All breeds</option>','<option value="all">All breeds</option>')}</select></div><div class="filter-group"><h3>District</h3><select data-filter="district">${optionsHTML(CONFIG.districts.map(x=>({value:x,label:x})),f.district,'All districts').replace('<option value="">All districts</option>','<option value="all">All districts</option>')}</select></div><div class="filter-group"><h3>Maximum price</h3><div class="filter-range-labels"><span>Rs. 0</span><strong data-range-label>${formatPrice(f.maxPrice)}</strong></div><input type="range" min="5000" max="200000" step="5000" value="${f.maxPrice}" data-filter="maxPrice"></div><div class="filter-group"><h3>Age range</h3><select data-filter="age"><option value="all">Any age</option><option value="young">Under 1 year</option><option value="adult">1–4 years</option><option value="mature">5 years +</option></select></div><div class="filter-group"><h3>Weight</h3><select data-filter="weight"><option value="all">Any weight</option><option value="under25">Under 25 kg</option><option value="25to100">25–100 kg</option><option value="over100">Over 100 kg</option></select></div><div class="filter-group"><label class="filter-option"><input type="checkbox" data-filter="vet" ${f.vet?'checked':''}> Vet-checked only</label></div><div class="filter-group"><h3>Sort by</h3><select data-filter="sort"><option value="featured">Featured</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="age">Age</option></select></div><button class="btn btn-outline btn-small filter-clear" data-action="clear-filters">Clear filters</button></aside>`;
if(dept==='meat')return `<aside class="filter-sidebar" id="filterSidebar"><div class="filter-head"><strong>Filter cuts</strong><button class="plain-link" data-action="clear-filters">Clear</button></div><div class="filter-group"><h3>Type of meat</h3>${['all','buffalo','goat','chicken'].map(x=>`<label class="filter-option"><input type="radio" name="categoryFilter" value="${x}" data-filter="category" ${f.category===x?'checked':''}> ${x==='all'?'All cuts':x[0].toUpperCase()+x.slice(1)}</label>`).join('')}<label class="filter-option"><input type="radio" name="categoryFilter" value="combo" data-filter="category" ${f.category==='combo'?'checked':''}> Sharing packs</label></div><div class="filter-group"><h3>Cut type</h3><select data-filter="cut">${optionsHTML(['Curry cut','Boneless','Mince / Keema','Ribs','Liver','Leg','Wings','Whole','Bones','Sharing pack'],'all','All cuts')}</select></div><div class="filter-group"><h3>Cooking method</h3>${['Curry','Grill','Fry','Roast','Soup'].map(x=>`<label class="filter-option"><input type="checkbox" data-method-filter="${x}" ${f.method.includes(x)?'checked':''}> ${x}</label>`).join('')}</div><div class="filter-group"><h3>Maximum price</h3><div class="filter-range-labels"><span>Rs. 0</span><strong data-range-label>${formatPrice(f.maxPrice)}</strong></div><input type="range" min="300" max="10000" step="100" value="${f.maxPrice}" data-filter="maxPrice"></div><div class="filter-group"><label class="filter-option"><input type="checkbox" data-filter="sale" ${f.sale?'checked':''}> On sale</label><label class="filter-option"><input type="checkbox" data-filter="stock" ${f.stock?'checked':''}> In stock only</label></div><div class="filter-group"><h3>Sort by</h3><select data-filter="sort"><option value="featured">Featured</option><option value="low">Price low to high</option><option value="high">Price high to low</option><option value="name">Name A–Z</option></select></div><button class="btn btn-outline btn-small filter-clear" data-action="clear-filters">Clear filters</button></aside>`;
if(dept==='produce')return `<aside class="filter-sidebar" id="filterSidebar"><div class="filter-head"><strong>Farm produce</strong><button class="plain-link" data-action="clear-filters">Clear</button></div><div class="filter-group"><h3>Product type</h3><select data-filter="category">${optionsHTML(['Milk','Eggs','Honey','Cheese','Ghee','Yogurt','Compost','Manure'],'all','All produce')}</select></div><div class="filter-group"><h3>Maximum price</h3><div class="filter-range-labels"><span>Rs. 0</span><strong data-range-label>${formatPrice(f.maxPrice)}</strong></div><input type="range" min="100" max="5000" step="100" data-filter="maxPrice" value="${f.maxPrice}"></div><div class="filter-group"><h3>Sort by</h3><select data-filter="sort"><option value="featured">Featured</option><option value="low">Price low to high</option><option value="high">Price high to low</option><option value="name">Name A–Z</option></select></div></aside>`;
if(dept==='supplies')return `<aside class="filter-sidebar" id="filterSidebar"><div class="filter-head"><strong>Find essentials</strong><button class="plain-link" data-action="clear-filters">Clear</button></div><div class="filter-group"><h3>Pet type</h3><select data-filter="petType">${optionsHTML(['Dogs','Cats','Birds','Dogs & Cats','Small pets'],'all','All pets')}</select></div><div class="filter-group"><h3>Size</h3><select data-filter="size">${optionsHTML(['S','M','L','Small','Medium','Large','Standard'],'all','All sizes')}</select></div><div class="filter-group"><h3>Brand</h3><select data-filter="brand">${optionsHTML([...new Set(PRODUCTS.filter(p=>p.department==='supplies').map(p=>p.brand))],'all','All brands')}</select></div><div class="filter-group"><h3>Maximum price</h3><div class="filter-range-labels"><span>Rs. 0</span><strong data-range-label>${formatPrice(f.maxPrice)}</strong></div><input type="range" min="200" max="8000" step="100" data-filter="maxPrice" value="${f.maxPrice}"></div><div class="filter-group"><h3>Sort by</h3><select data-filter="sort"><option value="featured">Featured</option><option value="low">Price low to high</option><option value="high">Price high to low</option><option value="name">Name A–Z</option></select></div></aside>`;
if(dept==='pets')return `<aside class="filter-sidebar" id="filterSidebar"><div class="filter-head"><strong>Find a companion</strong><button class="plain-link" data-action="clear-filters">Clear</button></div><div class="filter-group"><h3>Animal type</h3><select data-filter="species">${optionsHTML(['Dog','Cat','Bird','Small pet'],'all','All pets')}</select></div><div class="filter-group"><h3>Listing type</h3><select data-filter="listingType">${optionsHTML(['Buy','Adopt'],'all','Buy or adopt')}</select></div><div class="filter-group"><h3>Sort by</h3><select data-filter="sort"><option value="featured">Featured</option><option value="age">Age</option><option value="low">Price low to high</option></select></div></aside>`;
if(dept==='vets')return `<aside class="filter-sidebar" id="filterSidebar"><div class="filter-head"><strong>Find a professional</strong><button class="plain-link" data-action="clear-filters">Clear</button></div><div class="filter-group"><h3>Specialization</h3><select data-filter="specialization">${optionsHTML(['Large animal','Small animal','Poultry','Aquatic'],'all','All specialties')}</select></div><div class="filter-group"><h3>City</h3><select data-filter="city">${optionsHTML(CONFIG.cities,'all','All cities')}</select></div><div class="filter-group"><h3>Visit type</h3><select data-filter="visitType">${optionsHTML(['Clinic','Home visit','Video consult','Emergency'],'all','All visit types')}</select></div><div class="filter-group"><h3>Availability</h3><select data-filter="availability">${optionsHTML(['Today','This week'],'all','Any available time')}</select></div></aside>`;
return `<aside class="filter-sidebar" id="filterSidebar"><div class="filter-head"><strong>Browse guides</strong><button class="plain-link" data-action="clear-filters">Clear</button></div><div class="filter-group"><h3>Topic</h3><select data-filter="category">${optionsHTML(['Farm care','Pet wellbeing','Food safety','Farm produce'],'all','All topics')}</select></div></aside>`;}
function renderListing(dept){const intro=introContent[dept];setAccent(dept);let headingExtra='';if(dept==='vets')headingExtra=`<div class="emergency-banner"><div><h3>Is this an emergency?</h3><p>Do not wait for an online booking in a life-threatening situation. Contact a local emergency veterinary provider.</p></div><a class="btn" href="tel:${safeAttr(CONFIG.phone)}">Call ${escapeHTML(CONFIG.phone)}</a></div>`;
return `${routeHeading(dept,intro.desc)}${dept==='vets'?`<div class="container emergency-wrap">${headingExtra}</div>`:''}<section class="listing-section"><div class="container listing-layout">${sidebarHTML(dept)}<div class="listing-main">${dept==='learn'?renderPostTabs():''}<div class="list-toolbar"><p id="listingCount">Loading listings…</p><div class="sort-wrap"><button class="filter-toggle" data-action="toggle-filters">☷ Filters</button><label for="listingSort">Sort</label><select id="listingSort" data-filter="sort"><option value="${dept==='meat'?'featured':'featured'}">Featured</option><option value="${dept==='meat'?'low':'low'}">Price: low to high</option><option value="high">Price: high to low</option><option value="name">Name: A–Z</option></select></div></div><div id="listingResults" class="listing-results">${renderListingResults(dept)}</div><button class="btn btn-outline load-more" data-action="load-more" data-dept="${dept}" ${getFilteredItems(dept).length<=STORE.listLimits[dept]?'hidden':''}>Load more</button><p class="muted-text" style="font-size:.66rem;margin-top:18px">Listings and prices are sample data for demonstration. Verify details and availability with the relevant seller or professional.</p></div></div></section>`;}
function renderPostTabs(){const categories=['all',...new Set(POSTS.map(p=>p.category))];return `<div class="post-tabs" aria-label="Filter care guides">${categories.map(category=>`<button type="button" class="post-tab ${STORE.filters.learn.category===category?'active':''}" data-post-category="${safeAttr(category)}">${category==='all'?'All guides':escapeHTML(category)}</button>`).join('')}</div>`;}
function getFilteredItems(dept){const f=STORE.filters[dept];let list=[];if(dept==='live'){list=LIVE_ANIMALS.filter(a=>(f.species==='all'||keySlug(a.species)===f.species)&&(f.district==='all'||a.district===f.district)&&(f.breed==='all'||a.breed===f.breed)&&a.price<=f.maxPrice&&(!f.vet||a.vetChecked)&&(!f.age||f.age==='all'||(f.age==='young'&&a.age<1)||(f.age==='adult'&&a.age>=1&&a.age<5)||(f.age==='mature'&&a.age>=5))&&(!f.weight||f.weight==='all'||(f.weight==='under25'&&a.weight<25)||(f.weight==='25to100'&&a.weight>=25&&a.weight<=100)||(f.weight==='over100'&&a.weight>100)));if(f.sort==='price-low'||f.sort==='low')list.sort((a,b)=>a.price-b.price);else if(f.sort==='price-high'||f.sort==='high')list.sort((a,b)=>b.price-a.price);else if(f.sort==='age')list.sort((a,b)=>a.age-b.age);else list.sort((a,b)=>Number(b.featured)-Number(a.featured));return list;}
if(['meat','produce','supplies'].includes(dept)){list=PRODUCTS.filter(p=>p.department===dept);if(dept==='meat')list=list.filter(p=>(f.category==='all'||p.category===f.category||(f.category==='combo'&&p.category==='goat'&&p.cut==='Sharing pack')||(f.category==='combo'&&p.cut==='Sharing pack'))&&(f.cut==='all'||!f.cut||p.cut===f.cut)&&(!f.method.length||f.method.some(m=>p.cookingMethods.includes(m)))&&p.basePrice<=f.maxPrice&&(!f.sale||p.onSale)&&(!f.stock||p.inStock));if(dept==='produce')list=list.filter(p=>(f.category==='all'||!f.category||p.categoryLabel===f.category)&&p.basePrice<=f.maxPrice);if(dept==='supplies')list=list.filter(p=>(f.petType==='all'||p.petType===f.petType)&&(f.size==='all'||p.sizes.includes(f.size))&&(f.brand==='all'||p.brand===f.brand)&&p.basePrice<=f.maxPrice);if(f.sort==='low')list.sort((a,b)=>a.basePrice-b.basePrice);else if(f.sort==='high')list.sort((a,b)=>b.basePrice-a.basePrice);else if(f.sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));else list.sort((a,b)=>Number(b.featured)-Number(a.featured));return list;}
if(dept==='pets'){list=PETS.filter(p=>(f.species==='all'||p.species===f.species)&&(f.listingType==='all'||p.listingType===f.listingType));if(f.sort==='age')list.sort((a,b)=>a.ageMonths-b.ageMonths);else if(f.sort==='low')list.sort((a,b)=>a.price-b.price);else list.sort((a,b)=>Number(b.featured)-Number(a.featured));return list;}
if(dept==='vets'){list=VETS.filter(v=>(f.specialization==='all'||v.specialization===f.specialization)&&(f.city==='all'||v.city===f.city)&&(f.visitType==='all'||v.visitTypes.includes(f.visitType))&&(f.availability==='all'||(f.availability==='Today'&&v.availableDays.includes(new Date().getDay()))||(f.availability==='This week'&&v.availableDays.length>=4)));return list.sort((a,b)=>b.rating-a.rating);}
if(dept==='learn'){list=POSTS.filter(p=>f.category==='all'||p.category===f.category);return list;}
return list;}
function renderListingResults(dept){const list=getFilteredItems(dept);const shown=list.slice(0,STORE.listLimits[dept]);const count=$('#listingCount');if(count)count.textContent=`${list.length} ${dept==='live'?'listings':dept==='vets'?'professionals':dept==='learn'?'guides':'items'} found`;if(!shown.length)return emptyState('Nothing matches just yet','Try clearing one or two filters to explore more listings.','Clear filters','#'+dept);if(dept==='live')return `<div class="live-list">${shown.map(a=>`<article class="animal-list-card" style="--accent:${departmentMeta('live').accent}"><a class="card-image" href="#animal/${a.id}">${imgTag(a.image,`${a.breed} on a farm`)}<span class="product-top-tags"><span class="badge">${a.vetChecked?'✓ Vet-checked':'Check details'}</span></span></a><div class="card-body"><div class="animal-main"><p class="card-overline">${escapeHTML(a.species)} · ${escapeHTML(a.gender)}</p><h3>${link(`#animal/${a.id}`,a.breed)}</h3><p>${escapeHTML(a.description)}</p><p>Listed by <strong>${escapeHTML(a.seller)}</strong></p></div><div class="animal-price">${formatPrice(a.price)}<small style="display:block;font-size:.64rem;color:var(--muted);font-weight:500">${escapeHTML(a.priceUnit)}</small></div><div class="animal-details-grid"><div><span>Age</span><strong>${escapeHTML(formatAge(a))}</strong></div><div><span>Weight</span><strong>${escapeHTML(a.weight)} kg</strong></div><div><span>District</span><strong>${escapeHTML(a.district)}</strong></div><div><span>Vaccination</span><strong>${a.vaccinated?'Reported':'Not listed'}</strong></div></div><div class="card-actions"><a class="btn btn-primary btn-small" href="#animal/${a.id}">Listing details →</a><button class="btn btn-outline btn-small" data-action="offer" data-id="${a.id}">Make an offer</button></div></div></article>`).join('')}</div>`;if(dept==='vets')return `<div class="cards-grid cols-2">${shown.map(renderVetCard).join('')}</div>`;if(dept==='learn')return `<div class="cards-grid cols-2">${shown.map(p=>`<article class="article-card"><a class="card-image" href="#learn/${p.id}">${imgTag(p.image,p.title)}</a><div class="card-body"><p class="card-overline">${escapeHTML(p.category)} · ${escapeHTML(p.read)}</p><h3>${link(`#learn/${p.id}`,p.title)}</h3><p>${escapeHTML(p.excerpt)}</p><a href="#learn/${p.id}" class="plain-link">Read article →</a></div></article>`).join('')}</div>`;return `<div class="listing-products">${shown.map(p=>dept==='pets'?renderPetCard(p):renderProductCard(p)).join('')}</div>`;}

function renderProductDetail(id){const p=getProduct(id);if(!p)return renderNotFound();setAccent(p.department);const d=departmentMeta(p.department);const related=PRODUCTS.filter(x=>x.department===p.department&&x.id!==p.id).slice(0,4);const isMeat=p.department==='meat'&&p.basePricePerKg;return `${routeHeading(p.department,`A closer look at ${p.name.toLowerCase()}.`)}<section class="listing-section"><div class="container"><div class="animal-detail-layout"><div class="detail-gallery"><img class="detail-main-image" id="detailMainImage" src="${safeAttr(p.image)}" alt="${safeAttr(p.name)}"> <div class="detail-thumbnails">${(p.images||[p.image]).map((src,i)=>`<button class="${i===0?'active':''}" data-action="detail-image" data-src="${safeAttr(src)}" aria-label="View image ${i+1}">${imgTag(src,p.name)}</button>`).join('')}</div></div><div class="detail-panel" style="--accent:${d.accent};--accent-soft:${d.soft}"><span class="category-pill">${escapeHTML(p.department==='meat'?p.categoryLabel:p.department==='produce'?'Farm source':p.department==='supplies'?'Pet essentials':p.department)}</span><h1>${escapeHTML(p.name)}</h1><div class="entity-meta"><span>★ ${p.rating.toFixed(1)} (${p.reviews} reviews)</span><span>${p.inStock?'● In stock':'○ Availability to confirm'}</span></div><div class="detail-price" id="detailPrice">${formatPrice(getUnitPrice(p,isMeat?1:(p.bulkBaseQty||1)))}${isMeat?'<small style="font-size:.72rem;color:var(--muted);font-weight:500"> / kg</small>':p.bulkBaseQty?`<small style="font-size:.72rem;color:var(--muted);font-weight:500"> / ${p.bulkBaseQty} kg pack</small>`:''}</div><p>${escapeHTML(p.description)}</p>${isMeat?`<div class="field"><span>Pack weight</span><select id="detailWeight" data-detail-weight="${p.id}"><option value="0.5">500 g</option><option value="1" selected>1 kg</option><option value="2">2 kg</option></select></div>`:p.cut==='Soil care'?`<div class="field"><span>Bulk quantity (minimum ${p.minOrder} kg)</span><select id="detailWeight" data-detail-weight="${p.id}">${p.bulkSizes.map(kg=>`<option value="${kg}" ${kg===p.bulkBaseQty?'selected':''}>${kg} kg</option>`).join('')}</select></div>`:p.department==='supplies'?`<div class="field"><span>Size / variant</span><select id="detailVariant">${optionsHTML(p.sizes||['Standard'],p.sizes?.[0]||'Standard',null)}</select></div><div class="field" style="margin-top:10px"><span>Colour</span><select id="detailColor">${optionsHTML(p.colors||['Natural'],'Natural',null)}</select></div>`:''}${p.subscription?`<div class="subscription-form"><label class="field"><span>Frequency</span><select id="detailCadence"><option>Daily</option><option>Alternate days</option><option>Weekly</option></select></label><label class="field"><span>Quantity</span><select id="detailSubQty"><option value="1">1 unit</option><option value="2">2 units</option><option value="3">3 units</option><option value="4">4 units</option></select></label><label class="field"><span>Start date</span><input id="detailStartDate" type="date" min="${todayISO()}" value="${todayISO()}"></label><button class="btn btn-primary" data-action="detail-subscribe" data-id="${p.id}">Set subscription →</button></div>`:`<div class="weight-qty-row"><strong style="font-size:.75rem">Quantity</strong><div class="qty-control"><button data-action="detail-qty" data-delta="-1" aria-label="Decrease quantity">−</button><span id="detailQty">1</span><button data-action="detail-qty" data-delta="1" aria-label="Increase quantity">+</button></div></div><div class="detail-buttons"><button class="btn btn-primary" data-action="detail-add" data-id="${p.id}">Add to basket</button><button class="btn btn-outline" data-action="quick-view" data-id="${p.id}">Quick view</button></div>`}<ul class="detail-info-list"><li><strong>About this item</strong><span>${escapeHTML(p.cut||p.categoryLabel)}</span></li><li><strong>Care / storage</strong><span>${escapeHTML(p.department==='meat'?'Keep chilled':p.department==='produce'?'Follow label instructions':'Use as directed')}</span></li><li><strong>Helpful note</strong><span>${escapeHTML(p.tips)}</span></li>${p.department==='meat'?`<li><strong>Typical nutrition</strong><span>${p.nutrition.calories} kcal · ${p.nutrition.protein} g protein</span></li>`:''}</ul><p class="muted-text" style="font-size:.69rem">Prices, availability, seller and delivery details are sample values. Verify details before placing a real order.</p></div></div><div class="section-heading" style="margin-top:65px"><div><p class="eyebrow">GOOD COMPANY</p><h2>You may also <em>like.</em></h2></div></div><div class="cards-grid">${related.map(renderProductCard).join('')}</div></div></section>`;}
function renderLiveDetail(id){const a=getAnimal(id);if(!a)return renderNotFound();setAccent('live');return `${routeHeading('live',`A closer look at this ${a.species.toLowerCase()} listing.`)}<section class="listing-section"><div class="container"><div class="animal-detail-layout"><div class="detail-gallery"><img class="detail-main-image" id="detailMainImage" src="${safeAttr(a.image)}" alt="${safeAttr(a.breed)}"><div class="detail-thumbnails">${a.images.map((src,i)=>`<button class="${i===0?'active':''}" data-action="detail-image" data-src="${safeAttr(src)}" aria-label="View animal image ${i+1}">${imgTag(src,a.breed)}</button>`).join('')}</div><div class="health-record"><h3>Health & vaccination details</h3><p><strong>Vet check:</strong> ${escapeHTML(a.health)}</p><p><strong>Vaccination:</strong> ${escapeHTML(a.vaccination)}</p><p><strong>Important:</strong> Ask to see original documents and arrange an independent veterinary examination before buying.</p></div></div><div class="detail-panel" style="--accent:${departmentMeta('live').accent};--accent-soft:${departmentMeta('live').soft}"><span class="category-pill">${escapeHTML(a.species)} listing</span><h1>${escapeHTML(a.breed)}</h1><div class="badge-row">${a.vetChecked?'<span class="badge success">✓ Vet-checked (seller listing)</span>':'<span class="badge">Vet check not listed</span>'}${a.vaccinated?'<span class="badge success">Vaccination reported</span>':''}</div><div class="detail-price">${formatPrice(a.price)} <small style="font-size:.72rem;color:var(--muted);font-weight:500">${escapeHTML(a.priceUnit)}</small></div><p>${escapeHTML(a.description)}</p><ul class="detail-info-list"><li><strong>Age</strong><span>${escapeHTML(formatAge(a))}</span></li><li><strong>Weight</strong><span>${escapeHTML(a.weight)} kg (listed)</span></li><li><strong>Sex</strong><span>${escapeHTML(a.gender)}</span></li><li><strong>District</strong><span>${escapeHTML(a.district)}</span></li><li><strong>Seller</strong><span>${escapeHTML(a.seller)}</span></li></ul><div class="detail-buttons"><button class="btn btn-primary" data-action="offer" data-id="${a.id}">Make an offer</button><button class="btn btn-outline" data-action="request-visit" data-id="${a.id}">Request a visit</button></div><a class="btn btn-secondary" style="width:100%;margin-top:10px" target="_blank" rel="noopener" href="https://wa.me/${safeAttr(CONFIG.whatsapp)}?text=${encodeURIComponent(`Hello ${a.seller}, I'm interested in your ${a.breed} listing (${a.id}). Is it available? Please share the current health records and a suitable time to visit.`)}">WhatsApp seller ↗</a><p class="muted-text" style="font-size:.67rem;margin-top:18px">For safety, meet in an appropriate setting and verify seller identity, health records, ownership and transport before any payment.</p></div></div><div class="section-heading" style="margin-top:60px"><div><p class="eyebrow">MORE FROM THE FARM GATE</p><h2>Other animal <em>listings.</em></h2></div><a href="#live" class="text-link">View all <span>→</span></a></div><div class="cards-grid cols-3">${LIVE_ANIMALS.filter(x=>x.id!==a.id).slice(0,3).map(renderLiveCard).join('')}</div></div></section>`;}
function renderPetDetail(id){const p=getPet(id);if(!p)return renderNotFound();setAccent('pets');return `${routeHeading('pets',`Get to know ${p.name} before arranging a meet.`)}<section class="listing-section"><div class="container"><div class="animal-detail-layout"><div class="detail-gallery"><img class="detail-main-image" src="${safeAttr(p.image)}" alt="${safeAttr(p.name)}, ${safeAttr(p.breed)}"><div class="health-record"><h3>Health record</h3><p>${escapeHTML(p.health)}</p><p><strong>Vaccination:</strong> ${p.vaccinated?'Reported in listing':'Not listed — ask about it'}</p><p><strong>Deworming:</strong> ${p.dewormed?'Reported in listing':'Not listed — ask about it'}</p><p>Request original records and arrange a veterinary check before transfer.</p></div></div><div class="detail-panel" style="--accent:${departmentMeta('pets').accent};--accent-soft:${departmentMeta('pets').soft}"><span class="category-pill">${escapeHTML(p.listingType)} · ${escapeHTML(p.species)}</span><h1>Meet ${escapeHTML(p.name)}.</h1><h3 style="font:600 1.1rem var(--font-display);margin:0">${escapeHTML(p.breed)}</h3><div class="detail-price">${p.listingType==='Adopt'?'Adoption enquiry':formatPrice(p.price)}</div><p>${escapeHTML(p.description)}</p><ul class="detail-info-list"><li><strong>Age</strong><span>${escapeHTML(p.age)}</span></li><li><strong>Gender</strong><span>${escapeHTML(p.gender)}</span></li><li><strong>Temperament</strong><span>${escapeHTML(p.temperament)}</span></li><li><strong>Listing</strong><span>${escapeHTML(p.listingType)}</span></li></ul><h3 style="font:700 1.2rem var(--font-display)">Responsible ownership checklist</h3><p>Please confirm these points before sending an enquiry.</p><div class="checklist"><label><input type="checkbox" data-pet-check="space"> I can provide safe, appropriate housing and daily care.</label><label><input type="checkbox" data-pet-check="cost"> I have budgeted for food, preventive care and unexpected veterinary costs.</label><label><input type="checkbox" data-pet-check="time"> I can provide the time, enrichment and training this animal needs.</label><label><input type="checkbox" data-pet-check="records"> I will verify records and arrange a veterinary health check.</label></div><button class="btn btn-primary" style="width:100%" data-action="pet-enquire" data-id="${p.id}" disabled id="petEnquireButton">Enquire about ${escapeHTML(p.name)} →</button><p class="muted-text" style="font-size:.68rem">No pet is added to the cart. Enquiries are saved in this browser and must be followed up directly.</p></div></div><div class="section-heading" style="margin-top:60px"><div><p class="eyebrow">MORE COMPANIONS</p><h2>Meet other <em>animals.</em></h2></div><a href="#pets" class="text-link">Browse pets <span>→</span></a></div><div class="cards-grid cols-3">${PETS.filter(x=>x.id!==p.id).slice(0,3).map(renderPetCard).join('')}</div></div></section>`;}
function availableVetSlots(vetId,date){const vet=getVet(vetId);if(!vet)return [];const day=new Date(`${date||todayISO()}T12:00:00`).getDay();if(date===todayISO()){return vet.slots.filter(slot=>!STORE.appointments.some(a=>a.vetId===vetId&&a.date===date&&a.slot===slot&&a.status!=='Cancelled'));}if(!vet.availableDays.includes(day))return [];return vet.slots.filter(slot=>!STORE.appointments.some(a=>a.vetId===vetId&&a.date===date&&a.slot===slot&&a.status!=='Cancelled'));}
function renderVetDetail(id){const v=getVet(id);if(!v)return renderNotFound();setAccent('vets');const slots=availableVetSlots(v.id,todayISO());return `${routeHeading('vets','Review the clinic details and request a consultation.')}<section class="listing-section"><div class="container"><div class="vet-profile-header">${imgTag(v.image,v.name)}<div><p class="eyebrow">${escapeHTML(v.specialization)} · ${escapeHTML(v.city)}</p><h1>${escapeHTML(v.name)}</h1><p>${escapeHTML(v.clinic)} · ${v.experience} years' experience · ★ ${v.rating}</p><p>Registration listed: ${escapeHTML(v.registration)} — verify credentials independently.</p></div></div><div class="animal-detail-layout"><div><div class="detail-panel"><h2 style="font:700 1.6rem var(--font-display)">About the practice</h2><p>${escapeHTML(v.description)}</p><ul class="detail-info-list"><li><strong>Specialization</strong><span>${escapeHTML(v.specialization)}</span></li><li><strong>Location</strong><span>${escapeHTML(v.city)}</span></li><li><strong>Consultation fee</strong><span>${formatPrice(v.fee)} (listed)</span></li><li><strong>Visit options</strong><span>${escapeHTML(v.visitTypes.join(', '))}</span></li></ul><p style="font-size:.7rem;color:var(--muted)">This directory is sample data for demonstration. Please confirm professional registration, fee, availability and clinic details directly.</p></div><div class="health-record"><h3>Urgent concern?</h3><p>For a life-threatening emergency, call a local emergency veterinary provider. Do not delay urgent care while waiting for an online appointment.</p><a href="tel:${safeAttr(CONFIG.phone)}" class="btn btn-primary btn-small">Call ${escapeHTML(CONFIG.phone)}</a></div></div><div class="detail-panel"><p class="eyebrow">REQUEST A VISIT</p><h2 style="font:700 1.8rem var(--font-display)">Book with ${escapeHTML(v.name.split(' ').slice(-1)[0])}</h2><p>Request an available time. The appointment will be saved in this browser; the clinic must confirm it.</p><form id="vetBookingForm" class="modal-form" data-vet-id="${v.id}"><div class="form-grid"><label>Visit type<select name="visitType" required>${optionsHTML(v.visitTypes,'','Choose visit type')}</select></label><label>Date<input type="date" name="date" min="${todayISO()}" value="${todayISO()}" required></label><label>Time slot<select name="slot" id="vetSlotSelect" required>${optionsHTML(slots,'',slots.length?'Choose a time':'No slots listed for this date')}</select></label><label>Your name<input name="ownerName" required autocomplete="name" placeholder="Full name"></label><label>Phone<input name="phone" type="tel" required autocomplete="tel" placeholder="98XXXXXXXX"></label><label>Animal species<select name="species" required>${optionsHTML(['Cattle','Buffalo','Goat','Sheep','Pig','Poultry','Fish','Dog','Cat','Bird','Small pet'],'','Choose species')}</select></label><label>Animal age<input name="animalAge" required placeholder="e.g. 2 years"></label><label class="field-full">Problem / reason for visit<textarea name="problem" required minlength="5" placeholder="Describe the concern or reason for visit"></textarea></label></div><div class="form-error" aria-live="polite"></div><button class="btn btn-primary" type="submit">Request appointment →</button></form></div></div><div class="section-heading" style="margin-top:60px"><div><p class="eyebrow">OTHER PROFESSIONALS</p><h2>Explore other <em>vets.</em></h2></div><a href="#vets" class="text-link">View directory <span>→</span></a></div><div class="cards-grid cols-2">${VETS.filter(x=>x.id!==v.id).slice(0,2).map(renderVetCard).join('')}</div></div></section>`;}
function renderPost(id){const p=getPost(id);if(!p)return renderLearnListingPage();setAccent('learn');return `${routeHeading('learn',p.excerpt)}<article class="container article-content section"><p class="eyebrow">${escapeHTML(p.category)} · ${escapeHTML(p.read)}</p><h1 style="font:700 clamp(2.3rem,5vw,4.4rem)/1.05 var(--font-display);letter-spacing:-.05em;margin:0">${escapeHTML(p.title)}</h1>${imgTag(p.image,p.title,'article-hero',false)}<p>${escapeHTML(p.excerpt)}</p>${p.sections.map(([h,t])=>`<h2>${escapeHTML(h)}</h2><p>${escapeHTML(t)}</p>`).join('')}<div class="health-record"><h3>A thoughtful reminder</h3><p>These guides are general information, not veterinary or legal advice. Ask a qualified professional for advice tailored to a particular animal or situation.</p></div><p style="margin-top:28px">${link('#learn','← Back to Learn & care','text-link')}</p></article>`;}
function renderLearnListingPage(){return renderListing('learn');}
function renderCartPage(){setAccent('meat');const t=computeTotals();const subs=t.lines.filter(l=>l.type==='subscription');const regular=t.lines.filter(l=>l.type!=='subscription');const itemLines=lines=>lines.length?lines.map(renderCartLine).join(''):'';return `${routeHeading('meat','Review your selection and keep each next step simple.')}<section class="listing-section"><div class="container"><div class="section-heading"><div><p class="eyebrow">YOUR SELECTION</p><h2>Your <em>basket.</em></h2></div><a href="#meat" class="text-link">Continue shopping <span>→</span></a></div>${!t.lines.length?emptyState('Your basket is taking a breather','Explore the marketplace and add an item when you find what you need.','Explore products','#meat'):`<div class="cart-page-layout"><div><div class="cart-page-lines"><h3>One-time items <span class="muted-text">(${regular.length})</span></h3>${regular.length?itemLines(regular):'<p class="muted-text">No one-time items in your basket.</p>'}</div><div class="cart-page-lines" style="margin-top:20px"><h3>Subscriptions <span class="muted-text">(${subs.length})</span></h3>${subs.length?itemLines(subs):'<p class="muted-text">No subscription items in your basket.</p>'}</div><div class="delivery-progress"><strong>${t.remaining>0?`Add ${formatPrice(t.remaining)} more for free delivery.`:'You qualify for free delivery.'}</strong><div class="progress"><span style="width:${t.progress}%"></span></div></div></div><aside class="detail-panel cart-summary"><h2 style="font:700 1.8rem var(--font-display)">Order summary</h2>${renderTotalsHTML(t)}<p class="muted-text" style="font-size:.67rem">Discount and delivery are calculated from the sample configuration. Confirm final terms with the seller.</p><a href="#checkout" class="btn btn-primary" style="width:100%">Continue to checkout →</a><a href="#meat" class="btn btn-outline" style="width:100%;margin-top:9px">Keep browsing</a></aside></div>`}</div></section>`;}
function renderCartLine(line){const p=line.product;return `<article class="cart-line" data-line-id="${safeAttr(line.lineId)}">${imgTag(p.image,p.name)}<div><h3>${escapeHTML(p.name)}</h3><small>${line.type==='subscription'?`Subscription · ${escapeHTML(line.subscription?.cadence||'Frequency to confirm')} · starts ${escapeHTML(line.subscription?.startDate||'not set')}`:p.department==='meat'&&p.basePricePerKg?`${Number(line.weight)} kg pack`:p.cut==='Soil care'?`${Number(line.weight)} kg bulk`:line.variant?`Variant: ${escapeHTML(line.variant)}`:p.categoryLabel}</small><div class="qty-control"><button data-action="cart-qty" data-id="${safeAttr(line.lineId)}" data-delta="-1" aria-label="Decrease quantity">−</button><span>${line.qty}</span><button data-action="cart-qty" data-id="${safeAttr(line.lineId)}" data-delta="1" aria-label="Increase quantity">+</button></div><button class="remove-line" data-action="remove-line" data-id="${safeAttr(line.lineId)}">Remove</button></div><div class="line-price">${formatPrice(line.lineTotal)}</div></article>`;}
function renderTotalsHTML(t){return `<div class="totals-line"><span>Subtotal</span><strong>${formatPrice(t.subtotal)}</strong></div><div class="totals-line discount-line"><span>Website discount (${CONFIG.discountPercent}%)</span><strong>−${formatPrice(t.discount)}</strong></div><div class="totals-line"><span>Delivery</span><strong>${t.delivery?formatPrice(t.delivery):'FREE'}</strong></div>${CONFIG.taxPercent?`<div class="totals-line"><span>Tax (${CONFIG.taxPercent}%)</span><strong>${formatPrice(t.tax)}</strong></div>`:''}<div class="totals-line total"><span>Total</span><strong>${formatPrice(t.total)}</strong></div>`;}
function renderCheckout(){setAccent('meat');const t=computeTotals();if(!t.lines.length)return `${routeHeading('meat','A quick review before checkout.')}<section class="listing-section container">${emptyState('Nothing to check out yet','Add an item to your basket before entering customer details.','Shop fresh meat','#meat')}</section>`;const b=STORE.booking||{};return `${routeHeading('meat','Share the details needed to coordinate your order.')}<section class="listing-section"><div class="container"><div class="section-heading"><div><p class="eyebrow">ONE LAST CHECK</p><h2>Checkout, <em>with care.</em></h2></div></div><div class="cart-page-layout"><form id="checkoutForm" class="form-card checkout-form"><h2 style="font:700 1.55rem var(--font-display);margin:0">Your details</h2><div class="appointment-form-grid"><label class="form-field">Full name<input name="name" required autocomplete="name" placeholder="Your full name"></label><label class="form-field">Phone number<input name="phone" type="tel" required autocomplete="tel" placeholder="98XXXXXXXX"><small class="field-error" data-error="phone"></small></label><label class="form-field">Email address<input name="email" type="email" required autocomplete="email" placeholder="you@example.com"><small class="field-error" data-error="email"></small></label><label class="form-field">City / district<select name="city" required>${optionsHTML(CONFIG.cities,b.city||'','Choose location')}</select></label><label class="form-field field-full">Delivery address<input name="address" required autocomplete="street-address" placeholder="Street, tole, ward and house details"></label><label class="form-field">Landmark (optional)<input name="landmark" placeholder="Nearby landmark"></label><label class="form-field">Order fulfilment<select name="fulfilment" required><option ${b.fulfilment!=='Pick-Up'?'selected':''}>Delivery</option><option ${b.fulfilment==='Pick-Up'?'selected':''}>Pick-Up</option></select></label><label class="form-field">Preferred date<input name="date" type="date" min="${todayISO()}" value="${safeAttr(b.date&&b.date>=todayISO()?b.date:todayISO())}" required></label><label class="form-field">Preferred time<select name="slot" required>${optionsHTML(CONFIG.timeSlots,b.slot||'','Choose slot')}</select></label><label class="form-field field-full">Notes for the order<textarea name="notes" rows="3" placeholder="Any helpful details? (optional)"></textarea></label></div><h2 style="font:700 1.45rem var(--font-display);margin:14px 0 0">Payment method</h2><div class="payment-options"><label><input type="radio" name="payment" value="Cash on Delivery" checked><span><strong>Cash on Delivery</strong><small>Pay when the order arrives or at pickup.</small></span></label><label><input type="radio" name="payment" value="QR / Bank transfer"><span><strong>QR / Bank transfer</strong><small>Transfer details must be confirmed by the business.</small></span></label><label><input type="radio" name="payment" value="eSewa / Khalti"><span><strong>eSewa / Khalti</strong><small>Placeholder only — no live gateway is connected.</small></span></label></div><label class="filter-option"><input type="checkbox" name="agree" required> I have reviewed my order and understand the business must confirm availability and payment.</label><p class="field-error" id="checkoutError" aria-live="polite"></p><button type="submit" class="btn btn-primary" style="width:100%">Place order request · ${formatPrice(t.total)} →</button><p class="muted-text" style="font-size:.67rem">This demo stores a browser-side confirmation only. It does not charge payment or send the order to a server.</p></form><aside class="detail-panel cart-summary"><h2 style="font:700 1.7rem var(--font-display)">Your order</h2>${t.lines.map(l=>`<div class="totals-line"><span>${escapeHTML(l.product.name)} × ${l.qty}${l.type==='subscription'?` <small>(${escapeHTML(l.subscription?.cadence||'subscription')})</small>`:''}</span><strong>${formatPrice(l.lineTotal)}</strong></div>`).join('')}${renderTotalsHTML(t)}<div class="health-record"><h3>Delivery preference</h3><p>${escapeHTML(b.fulfilment||'Delivery')} · ${escapeHTML(b.city||'Choose location')}</p><p>${escapeHTML(b.date||'Date to confirm')} · ${escapeHTML(b.slot||'Time to confirm')}</p><p>Update the saved slot above if needed.</p></div><a href="#cart" class="text-link" style="margin-top:18px">Edit basket <span>→</span></a></aside></div></div></section>`;}
function renderWishlist(){setAccent('pets');const found=STORE.wishlist.map(id=>getProduct(id)||getPet(id)||getAnimal(id)).filter(Boolean);return `${routeHeading('pets','The animals and things you have saved in this browser.')}<section class="listing-section container"><div class="section-heading"><div><p class="eyebrow">SAVED FOR LATER</p><h2>Your <em>wishlist.</em></h2></div></div>${found.length?`<div class="cards-grid">${found.map(item=>getProduct(item.id)?renderProductCard(item):getPet(item.id)?renderPetCard(item):renderLiveCard(item)).join('')}</div>`:emptyState('Nothing saved yet','Tap the heart on a product to keep it close.','Explore the marketplace','#home')}</section>`;}
function renderAccount(){setAccent('learn');const b=STORE.booking||{};return `${routeHeading('learn','Your saved enquiries, vet appointment requests and browser-side order history.')}<section class="listing-section"><div class="container"><div class="section-heading"><div><p class="eyebrow">YOUR PASHU GHAR</p><h2>My <em>Pashu.</em></h2></div><a class="btn btn-outline btn-small" href="#wishlist">Open wishlist →</a></div><div class="account-tabs"><a href="#account" class="active">Overview</a><a href="#account#appointments" data-account-tab="appointments">Appointments</a><a href="#account#enquiries" data-account-tab="enquiries">Enquiries</a><a href="#account#orders" data-account-tab="orders">Orders</a></div><div class="cards-grid cols-3"><article class="why-card"><span class="why-icon">♡</span><h3>${STORE.wishlist.length} saved items</h3><p>Saved products and companion listings.</p><a href="#wishlist" class="plain-link">View wishlist →</a></article><article class="why-card"><span class="why-icon">✚</span><h3>${STORE.appointments.filter(a=>a.status!=='Cancelled').length} appointment requests</h3><p>Locally saved veterinary booking requests.</p><button class="plain-link" data-action="show-account-section" data-section="appointments">View appointments →</button></article><article class="why-card"><span class="why-icon">♧</span><h3>${STORE.enquiries.length} enquiries</h3><p>Animal offers, visits and pet enquiries.</p><button class="plain-link" data-action="show-account-section" data-section="enquiries">View enquiries →</button></article></div><div id="accountRecords" style="margin-top:35px">${renderAccountRecords('appointments')}</div><div class="health-record" style="margin-top:25px"><h3>Saved fulfilment preference</h3><p>${b.fulfilment?`${escapeHTML(b.fulfilment)} · ${escapeHTML(b.city||'Location not selected')} · ${escapeHTML(b.date||'Date not selected')} · ${escapeHTML(b.slot||'Time not selected')}`:'No booking preference saved yet.'}</p><a href="#home" class="plain-link">Update via quick actions →</a></div></div></section>`;}
function renderAccountRecords(section){if(section==='appointments')return `<h2 style="font:700 1.7rem var(--font-display)">My appointments</h2><div class="appointment-list">${STORE.appointments.length?STORE.appointments.map(a=>`<article class="saved-record"><div><span class="badge ${a.status==='Cancelled'?'danger':'success'}">${escapeHTML(a.status||'Requested')}</span><h3>${escapeHTML(a.vetName)} · ${escapeHTML(a.visitType)}</h3><p>Booking ID ${escapeHTML(a.id)} · ${escapeHTML(a.date)} · ${escapeHTML(a.slot)}</p><p>${escapeHTML(a.species)} (${escapeHTML(a.animalAge)}) · ${escapeHTML(a.ownerName)} · ${escapeHTML(a.phone)}</p><p>${escapeHTML(a.problem)}</p></div>${a.status==='Cancelled'?'':`<button class="btn btn-outline btn-small" data-action="cancel-appointment" data-id="${safeAttr(a.id)}">Cancel request</button>`}</article>`).join(''):emptyState('No appointment requests yet','Choose a vet and request an available slot.','Find a vet','#vets')}</div>`;if(section==='enquiries')return `<h2 style="font:700 1.7rem var(--font-display)">My enquiries</h2><div class="enquiry-list">${STORE.enquiries.length?STORE.enquiries.map(e=>`<article class="saved-record"><div><span class="badge">${escapeHTML(e.type||'Enquiry')}</span><h3>${escapeHTML(e.title||e.name||'Marketplace enquiry')}</h3><p>Reference ${escapeHTML(e.id)} · ${new Date(e.createdAt).toLocaleString()}</p><p>${escapeHTML(e.message||'')}</p><p class="muted-text">${escapeHTML(e.status)}</p></div></article>`).join(''):emptyState('No enquiries saved','Animal offers, visit requests and pet enquiries appear here.','Browse live animals','#live')}</div>`;if(section==='orders')return `<h2 style="font:700 1.7rem var(--font-display)">Order history</h2><div class="appointment-list">${STORE.orders.length?STORE.orders.map(o=>`<article class="saved-record"><div><span class="badge">${escapeHTML(o.status)}</span><h3>Order ${escapeHTML(o.id)}</h3><p>${new Date(o.createdAt).toLocaleString()} · ${formatPrice(o.total)}</p><p>${escapeHTML(o.name)} · ${escapeHTML(o.fulfilment)}</p></div><button class="btn btn-outline btn-small" data-action="order-whatsapp" data-id="${safeAttr(o.id)}">WhatsApp summary →</button></article>`).join(''):emptyState('No orders saved','A successful checkout request will appear here.','Shop products','#meat')}</div>`;return '';}
function renderAbout(){return `${routeHeading('learn','A marketplace built around practical care and useful connections.')}<section class="section content-page container"><p class="eyebrow">OUR PURPOSE</p><h2>Everything animals.<br><em>From farm to family.</em></h2><p>Pashu Ghar brings several everyday animal needs into one clear online experience: local livestock listings, fresh meat, farm produce, pet supplies, companion animals, veterinary appointments and educational guides.</p><p>We believe a useful marketplace should make it easier to find information and ask the right questions. Listings in this starter build are illustrative examples, not verified sellers or professional endorsements.</p><div class="health-record"><h3>Care and transparency first</h3><p>Before commercial launch, verify each seller and vet, publish clear business policies, add real contact details and connect secure server-side order and payment systems.</p></div><a href="#contact" class="btn btn-primary" style="margin-top:20px">Contact Pashu Ghar →</a></section>`;}
function renderContact(){return `${routeHeading('learn','Have a question about a listing, a product or a vet appointment?')}<section class="section content-page container"><p class="eyebrow">CONTACT</p><h2>Let's talk about <em>what you need.</em></h2><div class="contact-grid"><div><h3>Business details</h3><p><strong>Phone</strong><br><a href="tel:${safeAttr(CONFIG.phone)}">${escapeHTML(CONFIG.phone)}</a></p><p><strong>Email</strong><br><a href="mailto:${safeAttr(CONFIG.email)}">${escapeHTML(CONFIG.email)}</a></p><p><strong>Address</strong><br>${escapeHTML(CONFIG.address)}</p><p class="muted-text">Contact information is editable in CONFIG. Replace the sample values before you publish.</p><div class="health-record"><h3>Not sure where to start?</h3><p>Browse the department directory, check listing details and contact the seller or professional directly to confirm current availability.</p></div></div><form id="contactForm" class="contact-form"><label>Your name<input name="name" required autocomplete="name"></label><label>Email address<input name="email" type="email" required autocomplete="email"></label><label>Topic<select name="topic"><option>General question</option><option>Product order</option><option>Animal listing</option><option>Veterinary appointment</option><option>Technical issue</option></select></label><label>Message<textarea name="message" rows="5" required minlength="5"></textarea></label><button class="btn btn-primary" type="submit">Prepare email →</button><small>This opens your email app. To receive messages online, connect a form service or backend.</small></form></div></section>`;}
function renderTerms(){return `${routeHeading('learn','Information to review before running a real marketplace.')}<section class="section content-page container"><p class="eyebrow">TERMS & POLICIES</p><h2>Clear information.<br><em>Responsible decisions.</em></h2><h3>Marketplace terms</h3><p>Product, animal and veterinary listings on this demo are sample data. Availability, price, seller identity, registrations, health records and delivery details are not independently verified. Confirm all material details directly before purchase, transfer or booking.</p><h3>Privacy</h3><p>This website stores cart contents, wishlist choices, booking preferences, appointment requests, enquiry details and order confirmations in the current browser's localStorage. The demo has no shared server database and does not send this information to a central service. Do not enter sensitive information. A live launch requires a reviewed privacy policy and secure backend.</p><h3>Payments and orders</h3><p>Checkout provides sample payment choices only. No card, bank, eSewa or Khalti transaction is processed by this demo. An order confirmation is a browser-side request, not a merchant-confirmed order. Before launch, publish accurate prices, delivery terms, refunds, cancellations and payment details.</p><h3>Animal welfare and transfers</h3><p>Buyers should verify ownership, health and vaccination records, consult a qualified veterinary professional and plan suitable transport and housing. A listing badge is not a medical guarantee. Adoptions and purchases must prioritize the animal's welfare and comply with local requirements.</p><h3>Veterinary care</h3><p>Directory details, professional registrations, fees and availability are illustrative and must be independently verified. Booking requests are not confirmed appointments. In an urgent or life-threatening situation, contact a local emergency veterinary provider immediately rather than relying on online booking.</p><h3>Contact</h3><p>Update CONFIG with accurate business contact information and have all policies reviewed for the actual jurisdictions and services before launch.</p></section>`;}
function renderNotFound(){setAccent('learn');return `<section class="not-found">${animalLineArt('not-found-art')}<p class="eyebrow">OOPS, WRONG FIELD</p><h1>404</h1><p>We couldn't find that page. Let's guide you back to familiar ground.</p><div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap"><a class="btn btn-primary" href="#home">Back home →</a><a class="btn btn-outline" href="#live">Browse marketplace</a></div></section>`;}
function renderRoute(){const app=$('#app');if(!app)return;const raw=location.hash.replace(/^#/,'')||'home';const [route,...parts]=raw.split('/');let html='';if(route==='home'||route==='')html=renderHome();else if(['live','meat','produce','pets','supplies','vets','learn'].includes(route)&&parts.length===0)html=renderListing(route);else if(route==='product')html=renderProductDetail(parts.join('/'));else if(route==='animal'){const id=parts.join('/');html=id.startsWith('pet-')?renderPetDetail(id.slice(4)):renderLiveDetail(id);}else if(route==='vet'&&parts[0])html=renderVetDetail(parts[0]);else if(route==='learn'&&parts[0])html=renderPost(parts[0]);else if(route==='cart')html=renderCartPage();else if(route==='checkout')html=renderCheckout();else if(route==='wishlist')html=renderWishlist();else if(route==='account')html=renderAccount();else if(route==='about')html=renderAbout();else if(route==='contact')html=renderContact();else if(route==='terms')html=renderTerms();else html=renderNotFound();app.innerHTML=html;
  app.classList.remove('route-ready');void app.offsetWidth;app.classList.add('route-ready');
  const listingRoute=['live','meat','produce','supplies','pets','vets','learn'].includes(route)&&parts.length===0;if(listingRoute)refreshListing(route);if(route==='cart')renderCartDrawer();if(route==='account'&&raw.includes('#')){const sec=raw.split('#')[1];if(['appointments','enquiries','orders'].includes(sec)){const target=$('#accountRecords');if(target)target.innerHTML=renderAccountRecords(sec);}}updateCounters();observeReveal();document.title=`${route==='home'?'Home':(CONFIG.departments[route]?.label||({cart:'Your basket',checkout:'Checkout',wishlist:'Wishlist',account:'My Pashu',about:'About us',contact:'Contact',terms:'Terms & policies',product:'Product details',animal:'Animal details',vet:'Vet details'}[route]||'Learn & care'))} | ${CONFIG.businessName}`;if(window.scrollY>300)window.scrollTo({top:0,behavior:'smooth'});if(route==='home')startTestimonialTimer();}
function skeletonGridHTML(count=6){return `<div class="listing-skeleton-grid" aria-label="Loading listings">${Array.from({length:count},()=>`<div class="skeleton-card"><div class="skeleton-block skeleton-photo"></div><div class="skeleton-block skeleton-line wide"></div><div class="skeleton-block skeleton-line"></div><div class="skeleton-block skeleton-pill"></div></div>`).join('')}</div>`;}
function refreshListing(dept){const out=$('#listingResults');const f=STORE.filters[dept];if(out){out.innerHTML=skeletonGridHTML(dept==='live'?4:6);requestAnimationFrame(()=>{if(out.isConnected&&$('#listingResults')===out)out.innerHTML=renderListingResults(dept);const load=$('.load-more[data-dept]');if(load)load.hidden=getFilteredItems(dept).length<=STORE.listLimits[dept];});}$$('[data-filter]').forEach(el=>{const key=el.dataset.filter;if(key==='sort')el.value=f.sort||'featured';else if(f[key]!==undefined){if(el.type==='checkbox')el.checked=!!f[key];else if(el.type==='radio')el.checked=el.value===String(f[key]);else if(el.type!=='range')el.value=f[key];}});if(f.method)$$('[data-method-filter]').forEach(el=>el.checked=f.method.includes(el.dataset.methodFilter));$$('[data-range-label]').forEach(el=>el.textContent=formatPrice(f.maxPrice));const load=$('.load-more[data-dept]');if(load)load.hidden=getFilteredItems(dept).length<=STORE.listLimits[dept];}

// ============================== MODALS =================================
function openModal(content){const backdrop=$('#modalBackdrop'),panel=$('#modalContent');if(!backdrop||!panel)return;STORE.lastFocus=document.activeElement;panel.innerHTML=content;backdrop.hidden=false;document.body.classList.add('no-scroll');setTimeout(()=>$('#modalClose')?.focus(),20);}
function closeModal(){const backdrop=$('#modalBackdrop');if(backdrop)backdrop.hidden=true;document.body.classList.remove('no-scroll');STORE.lastFocus?.focus?.();}
function showQuickView(id){const p=getProduct(id);if(!p)return;const isMeat=p.department==='meat'&&p.basePricePerKg;openModal(`<div class="modal-product-layout"><img class="modal-product-image" src="${safeAttr(p.image)}" alt="${safeAttr(p.name)}"><div class="modal-product-details"><p class="eyebrow">${escapeHTML(p.department==='meat'?p.categoryLabel:p.department)}</p><h2 id="modalTitle">${escapeHTML(p.name)}</h2><div class="price">${formatPrice(getUnitPrice(p,isMeat?1:1))}${isMeat?' / kg':''}</div><p>${escapeHTML(p.description)}</p>${isMeat?`<label class="field"><span>Weight</span><select id="quickViewWeight"><option value="0.5">500 g</option><option value="1" selected>1 kg</option><option value="2">2 kg</option></select></label>`:''}${p.cut==='Soil care'?`<label class="field"><span>Bulk quantity</span><select id="quickViewWeight">${p.bulkSizes.map(kg=>`<option value="${kg}" ${kg===p.bulkBaseQty?'selected':''}>${kg} kg</option>`).join('')}</select></label>`:''}${p.department==='supplies'?`<label class="field"><span>Size / variant</span><select id="quickViewVariant">${optionsHTML(p.sizes||['Standard'],p.sizes?.[0]||'Standard',null)}</select></label><label class="field"><span>Colour</span><select id="quickViewColor">${optionsHTML(p.colors||['Natural'],'Natural',null)}</select></label>`:''}<div class="field" style="margin-top:12px"><span>Quantity</span><div class="qty-control"><button data-action="modal-qty" data-delta="-1">−</button><span id="modalQty">1</span><button data-action="modal-qty" data-delta="1">+</button></div></div><button class="btn btn-primary" style="width:100%;margin-top:17px" data-action="modal-add" data-id="${p.id}">Add to basket →</button><a class="text-link" style="margin-top:15px" href="#product/${p.id}" data-action="close-modal-link">Full product details →</a></div></div>`);}
function showSubscriptionModal(id){const p=getProduct(id);if(!p||!p.subscription)return;openModal(`<p class="eyebrow">FARM-TO-FRIDGE ROUTINE</p><h2 id="modalTitle">Set up ${escapeHTML(p.name)}</h2><p class="modal-lead">Choose a simple cadence. This saves a subscription line locally; recurring delivery and payment are not automated.</p><form class="modal-form" id="subscriptionForm" data-product-id="${p.id}"><div class="form-grid"><label>Frequency<select name="cadence" required><option>Daily</option><option>Alternate days</option><option>Weekly</option></select></label><label>Quantity<select name="qty" required><option value="1">1 unit per delivery</option><option value="2">2 units per delivery</option><option value="3">3 units per delivery</option><option value="4">4 units per delivery</option></select></label><label>Start date<input name="startDate" type="date" min="${todayISO()}" value="${todayISO()}" required></label><label>Delivery location<select name="city" required>${optionsHTML(CONFIG.cities,'','Choose location')}</select></label></div><p class="muted-text" style="font-size:.69rem">Listed price: ${formatPrice(p.basePrice)} per unit per delivery, before delivery and discount calculations.</p><button class="btn btn-primary" type="submit">Add subscription to basket →</button></form>`);}
function showAnimalOffer(id,mode='offer'){const a=getAnimal(id);if(!a)return;const visit=mode==='visit';openModal(`<p class="eyebrow">${visit?'PLAN A FARM VISIT':'START A CONVERSATION'}</p><h2 id="modalTitle">${visit?'Request a visit':'Make an offer'} for ${escapeHTML(a.breed)}</h2><p class="modal-lead">${visit?'Request a preferred date and time. The seller needs to confirm it.':'Share a considered offer with the seller. No payment is taken here.'}</p><form class="modal-form" id="animalEnquiryForm" data-animal-id="${a.id}" data-enquiry-type="${visit?'Visit request':'Offer'}"><div class="form-grid"><label>Your name<input name="name" required autocomplete="name"></label><label>Phone number<input name="phone" type="tel" required autocomplete="tel" placeholder="98XXXXXXXX"></label>${visit?`<label>Preferred date<input type="date" name="date" min="${todayISO()}" value="${todayISO()}" required></label><label>Preferred time<select name="slot" required>${optionsHTML(CONFIG.timeSlots,'','Choose a slot')}</select></label>`:`<label>Offer amount (Rs.)<input name="amount" type="number" min="1" required value="${a.price}"></label><label>Offer validity<select name="validity"><option>24 hours</option><option>3 days</option><option>1 week</option></select></label>`}<label class="field-full">Message<textarea name="message" rows="3" placeholder="Any questions for the seller?" required minlength="3"></textarea></label></div><p class="form-error" aria-live="polite"></p><button class="btn btn-primary" type="submit">Save ${visit?'visit request':'offer enquiry'} →</button></form>`);}
function showPetEnquiry(id){const p=getPet(id);if(!p)return;openModal(`<p class="eyebrow">RESPONSIBLE COMPANIONSHIP</p><h2 id="modalTitle">Enquire about ${escapeHTML(p.name)}</h2><p class="modal-lead">Share your contact details so you can arrange a thoughtful conversation with the current caregiver. No payment is taken here.</p><form id="petEnquiryForm" class="modal-form" data-pet-id="${p.id}"><div class="form-grid"><label>Your name<input name="name" required autocomplete="name"></label><label>Phone number<input name="phone" type="tel" required autocomplete="tel" placeholder="98XXXXXXXX"></label><label class="field-full">A note for the caregiver<textarea name="message" rows="3" required minlength="3" placeholder="Tell them a little about the home you can offer"></textarea></label></div><p class="form-error" aria-live="polite"></p><button class="btn btn-primary" type="submit">Save pet enquiry →</button></form>`);}
function showBookingSuccess(appointment){openModal(`<div class="modal-success"><div class="success-mark">✓</div><p class="eyebrow">REQUEST SAVED</p><h2 id="modalTitle">Your appointment request is ready.</h2><p>Keep the reference below. The clinic still needs to confirm the slot.</p><div class="order-code">${escapeHTML(appointment.id)}</div><p><strong>${escapeHTML(appointment.vetName)}</strong><br>${escapeHTML(appointment.date)} · ${escapeHTML(appointment.slot)}<br>${escapeHTML(appointment.visitType)}</p><a class="btn btn-primary" href="#account" data-action="close-modal-link">View My Appointments →</a></div>`);}
function showOrderSuccess(order){const summary=orderSummaryText(order);const url=`https://wa.me/${encodeURIComponent(CONFIG.whatsapp)}?text=${encodeURIComponent(summary)}`;openModal(`<div class="modal-success"><div class="success-mark">✓</div><p class="eyebrow">ORDER REQUEST SAVED</p><h2 id="modalTitle">Thank you, ${escapeHTML(order.name.split(' ')[0])}.</h2><p>Your browser has saved the order request. This is not a merchant-confirmed order, and no payment has been processed.</p><div class="order-code">${escapeHTML(order.id)}</div><p>Total shown: <strong>${formatPrice(order.total)}</strong><br>${escapeHTML(order.fulfilment)} · ${escapeHTML(order.date)} · ${escapeHTML(order.slot)}</p><div style="display:grid;gap:9px"><a class="btn btn-primary" href="${safeAttr(url)}" target="_blank" rel="noopener">Send order on WhatsApp ↗</a><a class="btn btn-outline" href="#account" data-action="close-modal-link">View order history</a><button class="btn btn-outline" data-action="print-order" type="button">Print confirmation</button></div></div>`);}
function orderSummaryText(order){return `${CONFIG.businessName} — Order request ${order.id}\nName: ${order.name}\nPhone: ${order.phone}\nEmail: ${order.email}\nLocation: ${order.city}\nAddress: ${order.address}${order.landmark?`\nLandmark: ${order.landmark}`:''}\nFulfilment: ${order.fulfilment}\nDate/time: ${order.date}, ${order.slot}\nPayment preference: ${order.payment}\n\nItems:\n${order.items.map(i=>`• ${i.name}${i.weight&&i.productId?` · ${i.weight} ${getProduct(i.productId)?.cut==='Soil care'?'kg bulk':getProduct(i.productId)?.department==='meat'&&getProduct(i.productId)?.basePricePerKg?'kg':''}`:''}${i.variant?` / ${i.variant}`:''} × ${i.qty}${i.type==='subscription'?` (${i.cadence})`:''}: ${formatPrice(i.total)}`).join('\n')}\nSubtotal: ${formatPrice(order.subtotal)}\nWebsite discount: -${formatPrice(order.discount)}\nDelivery: ${order.delivery?formatPrice(order.delivery):'Free'}\nTOTAL: ${formatPrice(order.total)}\nNotes: ${order.notes||'—'}\n\nPlease confirm stock, final price and delivery slot before processing.`;}

// ============================== ROUTE / STATE EVENTS ===================
function openCartDrawer(){const drawer=$('#cartDrawer'),backdrop=$('#drawerBackdrop');if(!drawer||!backdrop)return;drawer.classList.add('open');drawer.setAttribute('aria-hidden','false');backdrop.hidden=false;document.body.classList.add('no-scroll');renderCartDrawer();$('#cartClose')?.focus();}
function closeCartDrawer(){const drawer=$('#cartDrawer'),backdrop=$('#drawerBackdrop');drawer?.classList.remove('open');drawer?.setAttribute('aria-hidden','true');if(backdrop)backdrop.hidden=true;document.body.classList.remove('no-scroll');}
function renderCartDrawer(){const items=$('#cartItems'),footer=$('#cartDrawerFooter');if(!items||!footer)return;const t=computeTotals();items.innerHTML=t.lines.length?t.lines.map(renderCartLine).join(''):emptyState('Your basket is empty','A good place to start is the fresh meat counter.','Browse fresh meat','#meat');footer.innerHTML=t.lines.length?`${t.remaining?`<div class="delivery-progress">Add ${formatPrice(t.remaining)} more to reach free delivery.<div class="progress"><span style="width:${t.progress}%"></span></div></div>`:'<div class="delivery-progress">Free delivery threshold reached.</div>'}${renderTotalsHTML(t)}<a href="#cart" class="btn btn-primary" style="width:100%;margin-top:14px">Review basket →</a>`:`<a href="#meat" class="btn btn-primary" style="width:100%">Explore products →</a>`;updateCounters();}
function setSearchOpen(open){const overlay=$('#searchOverlay');if(!overlay)return;overlay.hidden=!open;if(open){document.body.classList.add('no-scroll');setTimeout(()=>$('#globalSearch')?.focus(),20);}else{document.body.classList.remove('no-scroll');$('#searchOpen')?.focus();}}
function renderSearchResults(query){const box=$('#searchResults');if(!box)return;const q=query.trim().toLowerCase();if(!q){box.innerHTML='<p class="muted-text">Popular searches: buffalo, eggs, kitten, vet</p>';return;}const hits=[];PRODUCTS.forEach(p=>{if(`${p.name} ${p.categoryLabel} ${p.cut} ${p.department} ${p.description}`.toLowerCase().includes(q))hits.push({type:'product',id:p.id,name:p.name,description:`${departmentMeta(p.department).label} · ${formatPrice(p.basePrice)}`,image:p.image,href:`#product/${p.id}`});});LIVE_ANIMALS.forEach(a=>{if(`${a.species} ${a.breed} ${a.district} ${a.seller}`.toLowerCase().includes(q))hits.push({type:'animal',id:a.id,name:a.breed,description:`Live ${a.species} · ${a.district} · ${formatPrice(a.price)}`,image:a.image,href:`#animal/${a.id}`});});PETS.forEach(p=>{if(`${p.name} ${p.species} ${p.breed} ${p.temperament}`.toLowerCase().includes(q))hits.push({type:'pet',id:p.id,name:`${p.name} · ${p.breed}`,description:`${p.listingType} · ${p.species}`,image:p.image,href:`#animal/pet-${p.id}`});});VETS.forEach(v=>{if(`${v.name} ${v.specialization} ${v.city} ${v.clinic}`.toLowerCase().includes(q))hits.push({type:'vet',id:v.id,name:v.name,description:`${v.specialization} · ${v.city}`,image:v.image,href:`#vet/${v.id}`});});POSTS.forEach(p=>{if(`${p.title} ${p.category} ${p.excerpt}`.toLowerCase().includes(q))hits.push({type:'post',id:p.id,name:p.title,description:`Guide · ${p.category}`,image:p.image,href:`#learn/${p.id}`});});box.innerHTML=hits.length?hits.slice(0,12).map(h=>`<a class="search-result" href="${safeAttr(h.href)}">${imgTag(h.image,h.name)}<span><strong>${escapeHTML(h.name)}</strong><small>${escapeHTML(h.description)}</small></span></a>`).join(''):`<div class="empty-state"><div class="empty-art">${animalLineArt()}</div><h3>No matching listings</h3><p>Try a different animal, product or care topic.</p></div>`;}
function resetFilters(dept){const defaults={live:{species:'all',district:'all',vet:false,sort:'featured',maxPrice:200000,breed:'all',age:'all',weight:'all'},meat:{category:'all',cut:'all',method:[],maxPrice:10000,sale:false,stock:true,sort:'featured'},produce:{category:'all',maxPrice:5000,sort:'featured'},supplies:{petType:'all',size:'all',brand:'all',maxPrice:8000,sort:'featured'},pets:{species:'all',listingType:'all',sort:'featured'},vets:{specialization:'all',city:'all',visitType:'all',availability:'all'},learn:{category:'all'}};STORE.filters[dept]={...defaults[dept]};STORE.listLimits[dept]=dept==='live'||dept==='pets'?8:dept==='learn'?6:12;refreshListing(dept);}
function refreshQuickAction(mode){STORE.currentQuickMode=mode;$$('[data-quick-mode]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.quickMode===mode)));const form=$('#quickActionForm');if(form){form.dataset.mode=mode;form.innerHTML=quickFields(mode)+`<button type="submit" class="btn btn-primary">${mode==='meat'?'Browse fresh cuts':mode==='animal'?'Find animals':'Find a vet'} <span>→</span></button>`;}}
function handleQuickAction(form){const data=new FormData(form);const mode=form.dataset.mode;if(mode==='meat'){STORE.booking={fulfilment:String(data.get('fulfilment')||'Delivery'),city:String(data.get('city')||''),date:String(data.get('date')||todayISO()),slot:String(data.get('slot')||'')};writeStorage(STORAGE_KEYS.booking,STORE.booking);STORE.filters.meat.category='all';toast('Your fulfilment preference has been saved.');routeTo('#meat');return;}if(mode==='animal'){STORE.filters.live.species=data.get('species')?keySlug(data.get('species')):'all';STORE.filters.live.district=String(data.get('district')||'all');STORE.filters.live.maxPrice=Number(data.get('budget')||200000);routeTo('#live');return;}const type=String(data.get('animalType')||'');if(type)STORE.filters.vets.specialization=type;STORE.filters.vets.city=String(data.get('city')||'all');routeTo('#vets');}
function handleClick(event){const sectionLink=event.target.closest('a[href^="#"]');if(sectionLink&&['categories','how-it-works'].includes(sectionLink.getAttribute('href').slice(1))){event.preventDefault();const sectionId=sectionLink.getAttribute('href').slice(1);const scrollHome=()=>document.getElementById(sectionId)?.scrollIntoView({behavior:'smooth',block:'start'});if(location.hash!=='#home'){routeTo('#home');setTimeout(scrollHome,90);}else scrollHome();return;}const target=event.target.closest('[data-action],[data-quick-mode],[data-category],[data-pet-species],[data-testimonial],[data-account-tab],[data-post-category]');if(!target)return;
  if(target.dataset.quickMode){refreshQuickAction(target.dataset.quickMode);return;}
  if(target.dataset.postCategory!==undefined){STORE.filters.learn.category=target.dataset.postCategory;STORE.listLimits.learn=6;refreshListing('learn');const tabs=$$('.post-tab');tabs.forEach(b=>b.classList.toggle('active',b.dataset.postCategory===STORE.filters.learn.category));return;}
  if(target.dataset.category){STORE.filters.meat.category=target.dataset.category;routeTo('#meat');return;}
  if(target.dataset.petSpecies){STORE.filters.pets.species=target.dataset.petSpecies;routeTo('#pets');return;}
  if(target.dataset.testimonial!==undefined){STORE.testimonialIndex=Number(target.dataset.testimonial);updateTestimonial();return;}
  if(target.dataset.accountTab){event.preventDefault();const sec=target.dataset.accountTab;const records=$('#accountRecords');if(records)records.innerHTML=renderAccountRecords(sec);$$('[data-account-tab]').forEach(a=>a.classList.toggle('active',a.dataset.accountTab===sec));return;}
  const action=target.dataset.action;const id=target.dataset.id;
  switch(action){
    case 'wishlist':toggleWishlist(id);target.classList.toggle('active',STORE.wishlist.includes(id));target.setAttribute('aria-pressed',String(STORE.wishlist.includes(id)));break;
    case 'add':{const p=getProduct(id);if(!p)return;const card=target.closest('[data-product-card]');const weight=Number($(`[data-weight-for="${id}"]`,card)?.value||$(`[data-bulk-qty-for="${id}"]`,card)?.value||1);const size=$(`[data-variant-for="${id}"]`,card)?.value||'';const color=$(`[data-color-for="${id}"]`,card)?.value||'';const variant=[size,color].filter(Boolean).join(' / ');const bulk=Boolean($(`[data-bulk-qty-for="${id}"]`,card));const qty=bulk?1:Number(STORE.cardQuantities?.[id]||1);addToCart(id,{weight,qty,variant});break;}
    case 'card-qty':{STORE.cardQuantities=STORE.cardQuantities||{};STORE.cardQuantities[id]=Math.max(1,Math.min(99,(STORE.cardQuantities[id]||1)+Number(target.dataset.delta)));const n=$(`[data-qty-for="${id}"]`);if(n)n.textContent=STORE.cardQuantities[id];break;}
    case 'quick-view':showQuickView(id);break;
    case 'subscribe':showSubscriptionModal(id);break;
    case 'detail-subscribe':{const p=getProduct(id);const cad=$('#detailCadence')?.value||'Daily';const qty=Number($('#detailSubQty')?.value||1);const startDate=$('#detailStartDate')?.value||todayISO();if(startDate<todayISO())return toast('Choose today or a future start date.');addToCart(id,{qty,subscription:{cadence:cad,startDate,city:STORE.booking?.city||''}});break;}
    case 'detail-add':{const p=getProduct(id);if(!p)return;const weight=Number($('#detailWeight')?.value||1);const size=$('#detailVariant')?.value||'';const color=$('#detailColor')?.value||'';const variant=[size,color].filter(Boolean).join(' / ');const qty=Number($('#detailQty')?.textContent||1);addToCart(id,{weight,variant,qty});break;}
    case 'detail-qty':{const n=$('#detailQty');if(n)n.textContent=Math.max(1,Math.min(99,Number(n.textContent||1)+Number(target.dataset.delta)));break;}
    case 'modal-qty':{const n=$('#modalQty');if(n)n.textContent=Math.max(1,Math.min(99,Number(n.textContent||1)+Number(target.dataset.delta)));break;}
    case 'modal-add':{const p=getProduct(id);if(!p)return;const weight=Number($('#quickViewWeight')?.value||1);const size=$('#quickViewVariant')?.value||'';const color=$('#quickViewColor')?.value||'';const variant=[size,color].filter(Boolean).join(' / ');const qty=Number($('#modalQty')?.textContent||1);addToCart(id,{weight,variant,qty});closeModal();break;}
    case 'cart-qty':updateCartQty(id,Number(target.dataset.delta));if(location.hash==='#cart')renderRoute();break;
    case 'remove-line':removeCartLine(id);if(location.hash==='#cart')renderRoute();break;
    case 'offer':showAnimalOffer(id,'offer');break;
    case 'request-visit':showAnimalOffer(id,'visit');break;
    case 'pet-enquire':{const ready=$$('[data-pet-check]').every(c=>c.checked);if(!ready)return toast('Please tick every responsible ownership item first.');showPetEnquiry(id);break;}
    case 'detail-image':{const img=$('#detailMainImage');if(img){img.src=target.dataset.src;$$('.detail-thumbnails button').forEach(b=>b.classList.toggle('active',b===target));}break;}
    case 'clear-filters':{const dept=location.hash.slice(1).split('/')[0];if(STORE.filters[dept])resetFilters(dept);break;}
    case 'toggle-filters':{$('#filterSidebar')?.classList.toggle('mobile-open');if(!$('.mobile-filter-overlay')){const overlay=document.createElement('div');overlay.className='mobile-filter-overlay';overlay.addEventListener('click',()=>{$('#filterSidebar')?.classList.remove('mobile-open');overlay.remove();});document.body.append(overlay);}else $('.mobile-filter-overlay')?.remove();break;}
    case 'load-more':{const dept=target.dataset.dept;STORE.listLimits[dept]+=dept==='live'||dept==='pets'?4:6;refreshListing(dept);break;}
    case 'show-account-section':{const sec=target.dataset.section;const records=$('#accountRecords');if(records)records.innerHTML=renderAccountRecords(sec);$$('[data-account-tab]').forEach(a=>a.classList.toggle('active',a.dataset.accountTab===sec));records?.scrollIntoView({behavior:'smooth',block:'start'});break;}
    case 'cancel-appointment':{const appointment=STORE.appointments.find(a=>a.id===id);if(appointment){appointment.status='Cancelled';writeStorage(STORAGE_KEYS.appointments,STORE.appointments);toast('Appointment request cancelled in this browser.');const rec=$('#accountRecords');if(rec)rec.innerHTML=renderAccountRecords('appointments');}break;}
    case 'order-whatsapp':{const order=STORE.orders.find(o=>o.id===id);if(order)window.open(`https://wa.me/${encodeURIComponent(CONFIG.whatsapp)}?text=${encodeURIComponent(orderSummaryText(order))}`,'_blank','noopener');break;}
    case 'print-order':window.print();break;
    case 'close-modal-link':closeModal();break;
  }
}

// ============================== FORM SUBMISSION ========================
document.addEventListener('submit',event=>{
  const form=event.target;if(!(form instanceof HTMLFormElement))return;
  if(form.id==='quickActionForm'){event.preventDefault();if(!form.reportValidity())return;handleQuickAction(form);return;}
  if(form.id==='subscriptionForm'){event.preventDefault();const id=form.dataset.productId;const data=new FormData(form);const startDate=String(data.get('startDate')||'');if(startDate<todayISO())return toast('Choose today or a future start date.');const subscription={cadence:String(data.get('cadence')),startDate,city:String(data.get('city'))};addToCart(id,{qty:Number(data.get('qty')||1),subscription});closeModal();return;}
  if(form.id==='animalEnquiryForm'){event.preventDefault();const data=new FormData(form);const phone=String(data.get('phone')||'');if(!validatePhone(phone)){showFormError(form,'Please enter a valid phone number.');return;}const a=getAnimal(form.dataset.animalId);if(!a)return;const isVisit=form.dataset.enquiryType==='Visit request';saveEnquiry({type:form.dataset.enquiryType,title:a.breed,animalId:a.id,name:String(data.get('name')),phone,message:isVisit?`Visit requested for ${data.get('date')} at ${data.get('slot')}. ${data.get('message')}`:`Offer ${formatPrice(data.get('amount'))}; validity ${data.get('validity')}. ${data.get('message')}`,amount:data.get('amount')||null,date:data.get('date')||null,slot:data.get('slot')||null});closeModal();return;}
  if(form.id==='petEnquiryForm'){event.preventDefault();const data=new FormData(form);const phone=String(data.get('phone')||'');if(!validatePhone(phone)){showFormError(form,'Please enter a valid phone number.');return;}const p=getPet(form.dataset.petId);if(!p)return;saveEnquiry({type:'Pet enquiry',title:`${p.name} · ${p.breed}`,petId:p.id,name:String(data.get('name')),phone,message:String(data.get('message'))+' Responsible ownership checklist acknowledged.'});closeModal();openModal(`<div class="modal-success"><div class="success-mark">✓</div><p class="eyebrow">ENQUIRY SAVED</p><h2 id="modalTitle">Your interest in ${escapeHTML(p.name)} is saved.</h2><p>Keep the listing reference <strong>${escapeHTML(p.id)}</strong> handy and contact the caregiver to confirm current availability, health records and a suitable meet-and-greet.</p><a href="#account" class="btn btn-primary" data-action="close-modal-link">View My Pashu →</a></div>`);return;}
  if(form.id==='vetBookingForm'){event.preventDefault();const data=new FormData(form);const phone=String(data.get('phone')||'');if(!validatePhone(phone)){showFormError(form,'Please enter a valid phone number.');return;}const vet=getVet(form.dataset.vetId);if(!vet)return;const date=String(data.get('date')||'');const slot=String(data.get('slot')||'');if(date<todayISO())return showFormError(form,'Choose today or a future date.');if(!availableVetSlots(vet.id,date).includes(slot))return showFormError(form,'That slot is no longer available. Please choose another.');const appointment={id:randomId('VET'),vetId:vet.id,vetName:vet.name,visitType:String(data.get('visitType')),date,slot,ownerName:String(data.get('ownerName')),phone,species:String(data.get('species')),animalAge:String(data.get('animalAge')),problem:String(data.get('problem')),status:'Requested',createdAt:new Date().toISOString()};STORE.appointments.unshift(appointment);writeStorage(STORAGE_KEYS.appointments,STORE.appointments);showBookingSuccess(appointment);return;}
  if(form.id==='checkoutForm'){event.preventDefault();const data=new FormData(form);const name=String(data.get('name')||'').trim(),phone=String(data.get('phone')||'').trim(),email=String(data.get('email')||'').trim();const err=$('#checkoutError');if(err)err.textContent='';$$('[data-error]').forEach(el=>el.textContent='');if(!validatePhone(phone)){if($('[data-error="phone"]'))$('[data-error="phone"]').textContent='Enter a valid phone number.';return;}if(!validateEmail(email)){if($('[data-error="email"]'))$('[data-error="email"]').textContent='Enter a valid email address.';return;}if(!name||!data.get('agree')){if(err)err.textContent='Enter your name and confirm the order acknowledgement.';return;}const totals=computeTotals();if(!totals.lines.length){toast('Your basket is empty.');routeTo('#cart');return;}const order={id:randomId('PG'),createdAt:new Date().toISOString(),name,phone,email,city:String(data.get('city')),address:String(data.get('address')),landmark:String(data.get('landmark')||''),fulfilment:String(data.get('fulfilment')),date:String(data.get('date')),slot:String(data.get('slot')),payment:String(data.get('payment')),notes:String(data.get('notes')||''),items:totals.lines.map(l=>({productId:l.productId,name:l.product.name,qty:l.qty,type:l.type,cadence:l.subscription?.cadence||'',weight:l.weight,variant:l.variant,total:l.lineTotal})),subtotal:totals.subtotal,discount:totals.discount,delivery:totals.delivery,tax:totals.tax,total:totals.total,status:'Local demo request'};STORE.orders.unshift(order);writeStorage(STORAGE_KEYS.orders,STORE.orders);STORE.cart=[];writeStorage(STORAGE_KEYS.cart,STORE.cart);STORE.subscriptions=[];writeStorage(STORAGE_KEYS.subscriptions,STORE.subscriptions);updateCounters();renderCartDrawer();showOrderSuccess(order);return;}
  if(form.id==='newsletterForm'||form.id==='footerNewsletter'){event.preventDefault();const email=String(new FormData(form).get('email')||'').trim();if(!validateEmail(email))return toast('Enter a valid email address.');const list=readStorage(STORAGE_KEYS.newsletter,[]);if(!list.includes(email))list.push(email);writeStorage(STORAGE_KEYS.newsletter,list);form.reset();toast('Thanks — your preference is saved in this browser.');return;}
  if(form.id==='contactForm'){event.preventDefault();const data=new FormData(form);const name=String(data.get('name')||'').trim(),email=String(data.get('email')||'').trim(),message=String(data.get('message')||'').trim();if(!name||!validateEmail(email)||message.length<5)return toast('Please complete the contact form.');const topic=String(data.get('topic')||'General question');const subject=encodeURIComponent(`[${CONFIG.businessName}] ${topic}`);const body=encodeURIComponent(`Name: ${name}\nEmail: ${email}\nTopic: ${topic}\n\n${message}`);window.location.href=`mailto:${CONFIG.email}?subject=${subject}&body=${body}`;toast('Opening your email app.');return;}
});
function showFormError(form,message){const node=$('.form-error',form);if(node)node.textContent=message;else toast(message);}

document.addEventListener('change',event=>{
 const el=event.target;
 if(el.matches('[data-filter]')){const dept=location.hash.slice(1).split('/')[0];if(!STORE.filters[dept])return;const key=el.dataset.filter;let val=el.type==='checkbox'?el.checked:el.value;if(el.type==='range')val=Number(val);if(key==='maxPrice')val=Number(val);STORE.filters[dept][key]=val;STORE.listLimits[dept]=dept==='learn'?6:dept==='live'||dept==='pets'?8:12;refreshListing(dept);}
 if(el.matches('[data-method-filter]')){const f=STORE.filters.meat;const method=el.dataset.methodFilter;if(el.checked&&!f.method.includes(method))f.method.push(method);else f.method=f.method.filter(m=>m!==method);refreshListing('meat');}
 if(el.matches('[data-weight-for]')){const p=getProduct(el.dataset.weightFor);const card=el.closest('[data-product-card]');const price=$('[data-live-price]',card);if(price&&p)price.textContent=formatPrice(getUnitPrice(p,Number(el.value)));}
 if(el.matches('[data-detail-weight]')){const p=getProduct(el.dataset.detailWeight);const price=$('#detailPrice');if(p&&price)price.innerHTML=`${formatPrice(getUnitPrice(p,Number(el.value)))} <small style="font-size:.72rem;color:var(--muted);font-weight:500"> ${p.cut==='Soil care'?`/ ${Number(el.value)} kg pack`:'/ kg'}</small>`;}
 if(el.matches('[data-pet-check]')){const button=$('#petEnquireButton');if(button)button.disabled=!$$('[data-pet-check]').every(c=>c.checked);}
 if(el.matches('#vetBookingForm [name="date"]')){const form=$('#vetBookingForm');const vetId=form?.dataset.vetId;const slot=$('#vetSlotSelect');if(slot&&vetId){const slots=availableVetSlots(vetId,el.value);slot.innerHTML=optionsHTML(slots,'',slots.length?'Choose a time':'No slots listed for this date');}}
 if(el.matches('[data-quick-mode]'))return;
});

document.addEventListener('input',event=>{const el=event.target;if(el.id==='globalSearch'){clearTimeout(searchDebounceTimer);searchDebounceTimer=setTimeout(()=>renderSearchResults(el.value),300);}if(el.matches('[data-filter="maxPrice"]')){const label=el.closest('.filter-group')?.querySelector('[data-range-label]');if(label)label.textContent=formatPrice(el.value);}});
window.addEventListener('hashchange',()=>{closeCartDrawer();closeModal();setSearchOpen(false);$('#mobileDrawer')?.classList.remove('open');$('#megaMenu')?.classList.remove('menu-open');$('#megaTrigger')?.setAttribute('aria-expanded','false');$('.mobile-filter-overlay')?.remove();renderRoute();});

// ============================== HEADER / SMALL INTERACTIONS ============
function updateTestimonial(){const t=TESTIMONIALS[STORE.testimonialIndex%TESTIMONIALS.length];const q=$('#testimonialText'),a=$('#testimonialAuthor');if(q)q.textContent=t.quote;if(a)a.textContent=t.author;$$('[data-testimonial]').forEach(b=>b.classList.toggle('active',Number(b.dataset.testimonial)===STORE.testimonialIndex));}
let testimonialTimer=null;let searchDebounceTimer=null;function startTestimonialTimer(){clearInterval(testimonialTimer);if(TESTIMONIALS.length<2)return;testimonialTimer=setInterval(()=>{if(document.hidden)return;STORE.testimonialIndex=(STORE.testimonialIndex+1)%TESTIMONIALS.length;updateTestimonial();},8000);}
function observeReveal(){const nodes=$$('.reveal:not(.revealed)');if(!('IntersectionObserver'in window)){nodes.forEach(n=>n.classList.add('revealed'));return;}const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('revealed');observer.unobserve(entry.target);}}),{threshold:.1});nodes.forEach(n=>observer.observe(n));}
function initHeader(){const announcement=readStorage('pashuGhar.announcementClosed',false);if(announcement&&$('#announcement'))$('#announcement').hidden=true;$('#closeAnnouncement')?.addEventListener('click',()=>{$('#announcement').hidden=true;writeStorage('pashuGhar.announcementClosed',true);});$('#searchOpen')?.addEventListener('click',()=>setSearchOpen(true));$('#searchClose')?.addEventListener('click',()=>setSearchOpen(false));$('#searchOverlay')?.addEventListener('click',e=>{if(e.target.id==='searchOverlay')setSearchOpen(false);});$('#cartOpen')?.addEventListener('click',openCartDrawer);$('#cartClose')?.addEventListener('click',closeCartDrawer);$('#drawerBackdrop')?.addEventListener('click',closeCartDrawer);$('#modalClose')?.addEventListener('click',closeModal);$('#modalBackdrop')?.addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal();});$('#menuToggle')?.addEventListener('click',()=>{const drawer=$('#mobileDrawer');drawer?.classList.add('open');drawer?.setAttribute('aria-hidden','false');$('#menuToggle')?.setAttribute('aria-expanded','true');document.body.classList.add('no-scroll');$('#mobileMenuClose')?.focus();});$('#mobileMenuClose')?.addEventListener('click',closeMobileMenu);$('#mobileDrawer')?.addEventListener('click',e=>{if(e.target.closest('a'))closeMobileMenu();});$('#megaTrigger')?.addEventListener('click',()=>{const expanded=$('#megaTrigger').getAttribute('aria-expanded')==='true';$('#megaTrigger').setAttribute('aria-expanded',String(!expanded));$('#megaMenu')?.classList.toggle('menu-open',!expanded);});$('#listingSort')?.addEventListener('change',e=>{const dept=location.hash.slice(1).split('/')[0];if(STORE.filters[dept]){STORE.filters[dept].sort=e.target.value;refreshListing(dept);}});$('#filterToggle')?.addEventListener('click',()=>{$('#filterSidebar')?.classList.toggle('mobile-open');});$('#bookingForm')?.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);const date=String(data.get('date'));if(date<todayISO())return toast('Choose today or a future date.');STORE.booking={fulfilment:String(data.get('fulfilment')),city:String(data.get('city')),date,slot:String(data.get('slot'))};writeStorage(STORAGE_KEYS.booking,STORE.booking);toast('Your preferred fulfilment slot is saved.');});}
function closeMobileMenu(){const drawer=$('#mobileDrawer');drawer?.classList.remove('open');drawer?.setAttribute('aria-hidden','true');$('#menuToggle')?.setAttribute('aria-expanded','false');document.body.classList.remove('no-scroll');}
function initBookingDates(){const inputs=$$('input[type="date"]');inputs.forEach(input=>{if(!input.min)input.min=todayISO();});const date=$('#bookingDate');if(date)date.value=todayISO();}
function init(){const year=$('#copyrightYear');if(year)year.textContent=String(new Date().getFullYear());const parts=CONFIG.businessName.trim().split(/\s+/);$$('.brand-wordmark').forEach(mark=>{const top=$('span',mark),bottom=$('strong',mark);if(top)top.textContent=parts.slice(0,-1).join(' ')||parts[0]||CONFIG.businessName;if(bottom)bottom.textContent=parts.length>1?parts.slice(-1).join(''):'';});$$('a[href^="mailto:"]').forEach(a=>{a.href=`mailto:${CONFIG.email}`;if(a.textContent.includes('@'))a.textContent=CONFIG.email;});$$('a[href^="tel:"]').forEach(a=>{a.href=`tel:${CONFIG.phone}`;if(a.textContent.includes('98')||a.textContent.includes('+977'))a.textContent=CONFIG.phone;});const app=$('#app');if(app)renderRoute();initHeader();initBookingDates();updateCounters();renderCartDrawer();observeReveal();document.addEventListener('click',handleClick);document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closeCartDrawer();setSearchOpen(false);closeMobileMenu();$('#megaMenu')?.classList.remove('menu-open');$('#megaTrigger')?.setAttribute('aria-expanded','false');$('.mobile-filter-overlay')?.remove();}if(e.key==='Tab'&&$('#modalBackdrop')&&!$('#modalBackdrop').hidden){const focusables=$$('#modalPanel a[href],#modalPanel button:not([disabled]),#modalPanel input:not([disabled]),#modalPanel select:not([disabled]),#modalPanel textarea:not([disabled])');if(!focusables.length)return;const first=focusables[0],last=focusables[focusables.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
